const e="0.2.0",t="2026-01-06T15:40:47.662Z",i={spec:"https://www.w3.org/TR/WCAG22/",json:"https://www.w3.org/WAI/WCAG22/wcag.json"},n=JSON.parse(`[{"id":"non-text-content","num":"1.1.1","title":"Non-text Content","level":"A","principle":"Perceivable","guideline":"1.1","guidelineTitle":"Text Alternatives","contentText":"All non-text content that is presented to the user has a text alternative that serves the equivalent purpose, except for the situations listed below. Controls, Input If non-text content is a control or accepts user input, then it has a name that describes its purpose. (Refer to Success Criterion 4.1.2 for additional requirements for controls and content that accepts user input.) Time-Based Media If non-text content is time-based media, then text alternatives at least provide descriptive identification of the non-text content. (Refer to Guideline 1.2 for additional requirements for media.) Test If non-text content is a test or exercise that would be invalid if presented in text , then text alternatives at least provide descriptive identification of the non-text content. Sensory If non-text content is primarily intended to create a specific sensory experience , then text alternatives at least provide descriptive identification of the non-text content. CAPTCHA If the purpose of non-text content is to confirm that content is being accessed by a person rather than a computer, then text alternatives that identify and describe the purpose of the non-text content are provided, and alternative forms of CAPTCHA using output modes for different types of sensory perception are provided to accommodate different disabilities. Decoration, Formatting, Invisible If non-text content is pure decoration , is used only for visual formatting, or is not presented to users, then it is implemented in a way that it can be ignored by assistive technology ."},{"id":"audio-only-and-video-only-prerecorded","num":"1.2.1","title":"Audio-only and Video-only (Prerecorded)","level":"A","principle":"Perceivable","guideline":"1.2","guidelineTitle":"Time-based Media","contentText":"For prerecorded audio-only and prerecorded video-only media, the following are true, except when the audio or video is a media alternative for text and is clearly labeled as such: Prerecorded Audio-only An alternative for time-based media is provided that presents equivalent information for prerecorded audio-only content. Prerecorded Video-only Either an alternative for time-based media or an audio track is provided that presents equivalent information for prerecorded video-only content."},{"id":"captions-prerecorded","num":"1.2.2","title":"Captions (Prerecorded)","level":"A","principle":"Perceivable","guideline":"1.2","guidelineTitle":"Time-based Media","contentText":"Captions are provided for all prerecorded audio content in synchronized media , except when the media is a media alternative for text and is clearly labeled as such."},{"id":"audio-description-or-media-alternative-prerecorded","num":"1.2.3","title":"Audio Description or Media Alternative (Prerecorded)","level":"A","principle":"Perceivable","guideline":"1.2","guidelineTitle":"Time-based Media","contentText":"An alternative for time-based media or audio description of the prerecorded video content is provided for synchronized media , except when the media is a media alternative for text and is clearly labeled as such."},{"id":"captions-live","num":"1.2.4","title":"Captions (Live)","level":"AA","principle":"Perceivable","guideline":"1.2","guidelineTitle":"Time-based Media","contentText":"Captions are provided for all live audio content in synchronized media ."},{"id":"audio-description-prerecorded","num":"1.2.5","title":"Audio Description (Prerecorded)","level":"AA","principle":"Perceivable","guideline":"1.2","guidelineTitle":"Time-based Media","contentText":"Audio description is provided for all prerecorded video content in synchronized media ."},{"id":"sign-language-prerecorded","num":"1.2.6","title":"Sign Language (Prerecorded)","level":"AAA","principle":"Perceivable","guideline":"1.2","guidelineTitle":"Time-based Media","contentText":"Sign language interpretation is provided for all prerecorded audio content in synchronized media ."},{"id":"extended-audio-description-prerecorded","num":"1.2.7","title":"Extended Audio Description (Prerecorded)","level":"AAA","principle":"Perceivable","guideline":"1.2","guidelineTitle":"Time-based Media","contentText":"Where pauses in foreground audio are insufficient to allow audio descriptions to convey the sense of the video, extended audio description is provided for all prerecorded video content in synchronized media ."},{"id":"media-alternative-prerecorded","num":"1.2.8","title":"Media Alternative (Prerecorded)","level":"AAA","principle":"Perceivable","guideline":"1.2","guidelineTitle":"Time-based Media","contentText":"An alternative for time-based media is provided for all prerecorded synchronized media and for all prerecorded video-only media."},{"id":"audio-only-live","num":"1.2.9","title":"Audio-only (Live)","level":"AAA","principle":"Perceivable","guideline":"1.2","guidelineTitle":"Time-based Media","contentText":"An alternative for time-based media that presents equivalent information for live audio-only content is provided."},{"id":"info-and-relationships","num":"1.3.1","title":"Info and Relationships","level":"A","principle":"Perceivable","guideline":"1.3","guidelineTitle":"Adaptable","contentText":"Information, structure , and relationships conveyed through presentation can be programmatically determined or are available in text."},{"id":"meaningful-sequence","num":"1.3.2","title":"Meaningful Sequence","level":"A","principle":"Perceivable","guideline":"1.3","guidelineTitle":"Adaptable","contentText":"When the sequence in which content is presented affects its meaning, a correct reading sequence can be programmatically determined ."},{"id":"sensory-characteristics","num":"1.3.3","title":"Sensory Characteristics","level":"A","principle":"Perceivable","guideline":"1.3","guidelineTitle":"Adaptable","contentText":"Instructions provided for understanding and operating content do not rely solely on sensory characteristics of components such as shape, color, size, visual location, orientation, or sound. Note For requirements related to color, refer to Guideline 1.4 ."},{"id":"orientation","num":"1.3.4","title":"Orientation","level":"AA","principle":"Perceivable","guideline":"1.3","guidelineTitle":"Adaptable","contentText":"Content does not restrict its view and operation to a single display orientation, such as portrait or landscape, unless a specific display orientation is essential . Note Examples where a particular display orientation may be essential are a bank check, a piano application, slides for a projector or television, or virtual reality content where content is not necessarily restricted to landscape or portrait display orientation."},{"id":"identify-input-purpose","num":"1.3.5","title":"Identify Input Purpose","level":"AA","principle":"Perceivable","guideline":"1.3","guidelineTitle":"Adaptable","contentText":"The purpose of each input field collecting information about the user can be programmatically determined when: The input field serves a purpose identified in the Input Purposes for user interface components section ; and The content is implemented using technologies with support for identifying the expected meaning for form input data."},{"id":"identify-purpose","num":"1.3.6","title":"Identify Purpose","level":"AAA","principle":"Perceivable","guideline":"1.3","guidelineTitle":"Adaptable","contentText":"In content implemented using markup languages, the purpose of user interface components , icons, and regions can be programmatically determined ."},{"id":"use-of-color","num":"1.4.1","title":"Use of Color","level":"A","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"Color is not used as the only visual means of conveying information, indicating an action, prompting a response, or distinguishing a visual element. Note This success criterion addresses color perception specifically. Other forms of perception are covered in Guideline 1.3 including programmatic access to color and other visual presentation coding."},{"id":"audio-control","num":"1.4.2","title":"Audio Control","level":"A","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"If any audio on a web page plays automatically for more than 3 seconds, either a mechanism is available to pause or stop the audio, or a mechanism is available to control audio volume independently from the overall system volume level. Note Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether or not it is used to meet other success criteria) must meet this success criterion. See Conformance Requirement 5: Non-Interference ."},{"id":"contrast-minimum","num":"1.4.3","title":"Contrast (Minimum)","level":"AA","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"The visual presentation of text and images of text has a contrast ratio of at least 4.5:1, except for the following: Large Text Large-scale text and images of large-scale text have a contrast ratio of at least 3:1; Incidental Text or images of text that are part of an inactive user interface component , that are pure decoration , that are not visible to anyone, or that are part of a picture that contains significant other visual content, have no contrast requirement. Logotypes Text that is part of a logo or brand name has no contrast requirement."},{"id":"resize-text","num":"1.4.4","title":"Resize Text","level":"AA","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"Except for captions and images of text , text can be resized without assistive technology up to 200 percent without loss of content or functionality."},{"id":"images-of-text","num":"1.4.5","title":"Images of Text","level":"AA","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"If the technologies being used can achieve the visual presentation, text is used to convey information rather than images of text except for the following: Customizable The image of text can be visually customized to the user's requirements; Essential A particular presentation of text is essential to the information being conveyed. Note Logotypes (text that is part of a logo or brand name) are considered essential."},{"id":"contrast-enhanced","num":"1.4.6","title":"Contrast (Enhanced)","level":"AAA","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"The visual presentation of text and images of text has a contrast ratio of at least 7:1, except for the following: Large Text Large-scale text and images of large-scale text have a contrast ratio of at least 4.5:1; Incidental Text or images of text that are part of an inactive user interface component , that are pure decoration , that are not visible to anyone, or that are part of a picture that contains significant other visual content, have no contrast requirement. Logotypes Text that is part of a logo or brand name has no contrast requirement."},{"id":"low-or-no-background-audio","num":"1.4.7","title":"Low or No Background Audio","level":"AAA","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"For prerecorded audio-only content that (1) contains primarily speech in the foreground, (2) is not an audio CAPTCHA or audio logo, and (3) is not vocalization intended to be primarily musical expression such as singing or rapping, at least one of the following is true: No Background The audio does not contain background sounds. Turn Off The background sounds can be turned off. 20 dB The background sounds are at least 20 decibels lower than the foreground speech content, with the exception of occasional sounds that last for only one or two seconds. Note Per the definition of \\"decibel,\\" background sound that meets this requirement will be approximately four times quieter than the foreground speech content."},{"id":"visual-presentation","num":"1.4.8","title":"Visual Presentation","level":"AAA","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"For the visual presentation of blocks of text , a mechanism is available to achieve the following: Foreground and background colors can be selected by the user. Width is no more than 80 characters or glyphs (40 if CJK). Text is not justified (aligned to both the left and the right margins). Line spacing (leading) is at least space-and-a-half within paragraphs, and paragraph spacing is at least 1.5 times larger than the line spacing. Text can be resized without assistive technology up to 200 percent in a way that does not require the user to scroll horizontally to read a line of text on a full-screen window . Note 1 Content is not required to use these values. The requirement is that a mechanism is available for users to change these presentation aspects. The mechanism can be provided by the browser or other user agent. Content is not required to provide the mechanism. Note 2 Writing systems for some languages use different presentation aspects to improve readability and legibility. If a presentation aspect in this success criterion is not used in a writing system, content in that writing system does not need to use that presentation setting and can conform without it. Authors are encouraged to follow guidance for improving readability and legibility of text in their writing system."},{"id":"images-of-text-no-exception","num":"1.4.9","title":"Images of Text (No Exception)","level":"AAA","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"Images of text are only used for pure decoration or where a particular presentation of text is essential to the information being conveyed. Note Logotypes (text that is part of a logo or brand name) are considered essential."},{"id":"reflow","num":"1.4.10","title":"Reflow","level":"AA","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"Content can be presented without loss of information or functionality, and without requiring scrolling in two dimensions for: Vertical scrolling content at a width equivalent to 320 CSS pixels ; Horizontal scrolling content at a height equivalent to 256 CSS pixels . Except for parts of the content which require two-dimensional layout for usage or meaning. Note 1 320 CSS pixels is equivalent to a starting viewport width of 1280 CSS pixels wide at 400% zoom. For web content which is designed to scroll horizontally (e.g., with vertical text), 256 CSS pixels is equivalent to a starting viewport height of 1024 CSS pixels at 400% zoom. Note 2 Examples of content which requires two-dimensional layout are images required for understanding (such as maps and diagrams), video, games, presentations, data tables (not individual cells), and interfaces where it is necessary to keep toolbars in view while manipulating content. It is acceptable to provide two-dimensional scrolling for such parts of the content."},{"id":"non-text-contrast","num":"1.4.11","title":"Non-text Contrast","level":"AA","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"The visual presentation of the following have a contrast ratio of at least 3:1 against adjacent color(s): User Interface Components Visual information required to identify user interface components and states , except for inactive components or where the appearance of the component is determined by the user agent and not modified by the author; Graphical Objects Parts of graphics required to understand the content, except when a particular presentation of graphics is essential to the information being conveyed."},{"id":"text-spacing","num":"1.4.12","title":"Text Spacing","level":"AA","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"In content implemented using markup languages that support the following text style properties , no loss of content or functionality occurs by setting all of the following and by changing no other style property: Line height (line spacing) to at least 1.5 times the font size; Spacing following paragraphs to at least 2 times the font size; Letter spacing (tracking) to at least 0.12 times the font size; Word spacing to at least 0.16 times the font size. Exception: Human languages and scripts that do not make use of one or more of these text style properties in written text can conform using only the properties that exist for that combination of language and script. Note 1 Content is not required to use these text spacing values. The requirement is to ensure that when a user overrides the authored text spacing, content or functionality is not lost. Note 2 Writing systems for some languages use different text spacing settings, such as paragraph start indent. Authors are encouraged to follow locally available guidance for improving readability and legibility of text in their writing system."},{"id":"content-on-hover-or-focus","num":"1.4.13","title":"Content on Hover or Focus","level":"AA","principle":"Perceivable","guideline":"1.4","guidelineTitle":"Distinguishable","contentText":"Where receiving and then removing pointer hover or keyboard focus triggers additional content to become visible and then hidden, the following are true: Dismissible A mechanism is available to dismiss the additional content without moving pointer hover or keyboard focus, unless the additional content communicates an input error or does not obscure or replace other content; Hoverable If pointer hover can trigger the additional content, then the pointer can be moved over the additional content without the additional content disappearing; Persistent The additional content remains visible until the hover or focus trigger is removed, the user dismisses it, or its information is no longer valid. Exception: The visual presentation of the additional content is controlled by the user agent and is not modified by the author. Note 1 Examples of additional content controlled by the user agent include browser tooltips created through use of the HTML title attribute [ HTML ]. Note 2 Custom tooltips, sub-menus, and other nonmodal popups that display on hover and focus are examples of additional content covered by this criterion. Note 3 This criterion applies to content that appears in addition to the triggering component itself. Since hidden components that are made visible on keyboard focus (such as links used to skip to another part of a page) do not present additional content they are not covered by this criterion."},{"id":"keyboard","num":"2.1.1","title":"Keyboard","level":"A","principle":"Operable","guideline":"2.1","guidelineTitle":"Keyboard Accessible","contentText":"All functionality of the content is operable through a keyboard interface without requiring specific timings for individual keystrokes, except where the underlying function requires input that depends on the path of the user's movement and not just the endpoints. Note 1 This exception relates to the underlying function, not the input technique. For example, if using handwriting to enter text, the input technique (handwriting) requires path-dependent input but the underlying function (text input) does not. Note 2 This does not forbid and should not discourage providing mouse input or other input methods in addition to keyboard operation."},{"id":"no-keyboard-trap","num":"2.1.2","title":"No Keyboard Trap","level":"A","principle":"Operable","guideline":"2.1","guidelineTitle":"Keyboard Accessible","contentText":"If keyboard focus can be moved to a component of the page using a keyboard interface , then focus can be moved away from that component using only a keyboard interface, and, if it requires more than unmodified arrow or tab keys or other standard exit methods, the user is advised of the method for moving focus away. Note Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether it is used to meet other success criteria or not) must meet this success criterion. See Conformance Requirement 5: Non-Interference ."},{"id":"keyboard-no-exception","num":"2.1.3","title":"Keyboard (No Exception)","level":"AAA","principle":"Operable","guideline":"2.1","guidelineTitle":"Keyboard Accessible","contentText":"All functionality of the content is operable through a keyboard interface without requiring specific timings for individual keystrokes."},{"id":"character-key-shortcuts","num":"2.1.4","title":"Character Key Shortcuts","level":"A","principle":"Operable","guideline":"2.1","guidelineTitle":"Keyboard Accessible","contentText":"If a keyboard shortcut is implemented in content using only letter (including upper- and lower-case letters), punctuation, number, or symbol characters, then at least one of the following is true: Turn off A mechanism is available to turn the shortcut off; Remap A mechanism is available to remap the shortcut to include one or more non-printable keyboard keys (e.g., Ctrl, Alt); Active only on focus The keyboard shortcut for a user interface component is only active when that component has focus."},{"id":"timing-adjustable","num":"2.2.1","title":"Timing Adjustable","level":"A","principle":"Operable","guideline":"2.2","guidelineTitle":"Enough Time","contentText":"For each time limit that is set by the content, at least one of the following is true: Turn off The user is allowed to turn off the time limit before encountering it; or Adjust The user is allowed to adjust the time limit before encountering it over a wide range that is at least ten times the length of the default setting; or Extend The user is warned before time expires and given at least 20 seconds to extend the time limit with a simple action (for example, \\"press the space bar\\"), and the user is allowed to extend the time limit at least ten times; or Real-time Exception The time limit is a required part of a real-time event (for example, an auction), and no alternative to the time limit is possible; or Essential Exception The time limit is essential and extending it would invalidate the activity; or 20 Hour Exception The time limit is longer than 20 hours. Note This success criterion helps ensure that users can complete tasks without unexpected changes in content or context that are a result of a time limit. This success criterion should be considered in conjunction with Success Criterion 3.2.1 , which puts limits on changes of content or context as a result of user action."},{"id":"pause-stop-hide","num":"2.2.2","title":"Pause, Stop, Hide","level":"A","principle":"Operable","guideline":"2.2","guidelineTitle":"Enough Time","contentText":"For moving, blinking , scrolling, or auto-updating information, all of the following are true: Moving, blinking, scrolling For any moving, blinking or scrolling information that (1) starts automatically, (2) lasts more than five seconds, and (3) is presented in parallel with other content, there is a mechanism for the user to pause , stop, or hide it unless the movement, blinking, or scrolling is part of an activity where it is essential ; and Auto-updating For any auto-updating information that (1) starts automatically and (2) is presented in parallel with other content, there is a mechanism for the user to pause, stop, or hide it or to control the frequency of the update unless the auto-updating is part of an activity where it is essential. Note 1 For requirements related to flickering or flashing content, refer to Guideline 2.3 . Note 2 Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether it is used to meet other success criteria or not) must meet this success criterion. See Conformance Requirement 5: Non-Interference . Note 3 Content that is updated periodically by software or that is streamed to the user agent is not required to preserve or present information that is generated or received between the initiation of the pause and resuming presentation, as this may not be technically possible, and in many situations could be misleading to do so. Note 4 An animation that occurs as part of a preload phase or similar situation can be considered essential if interaction cannot occur during that phase for all users and if not indicating progress could confuse users or cause them to think that content was frozen or broken."},{"id":"no-timing","num":"2.2.3","title":"No Timing","level":"AAA","principle":"Operable","guideline":"2.2","guidelineTitle":"Enough Time","contentText":"Timing is not an essential part of the event or activity presented by the content, except for non-interactive synchronized media and real-time events ."},{"id":"interruptions","num":"2.2.4","title":"Interruptions","level":"AAA","principle":"Operable","guideline":"2.2","guidelineTitle":"Enough Time","contentText":"Interruptions can be postponed or suppressed by the user, except interruptions involving an emergency ."},{"id":"re-authenticating","num":"2.2.5","title":"Re-authenticating","level":"AAA","principle":"Operable","guideline":"2.2","guidelineTitle":"Enough Time","contentText":"When an authenticated session expires, the user can continue the activity without loss of data after re-authenticating."},{"id":"timeouts","num":"2.2.6","title":"Timeouts","level":"AAA","principle":"Operable","guideline":"2.2","guidelineTitle":"Enough Time","contentText":"Users are warned of the duration of any user inactivity that could cause data loss, unless the data is preserved for more than 20 hours when the user does not take any actions. Note Privacy regulations may require explicit user consent before user identification has been authenticated and before user data is preserved. In cases where the user is a minor, explicit consent may not be solicited in most jurisdictions, countries or regions. Consultation with privacy professionals and legal counsel is advised when considering data preservation as an approach to satisfy this success criterion."},{"id":"three-flashes-or-below-threshold","num":"2.3.1","title":"Three Flashes or Below Threshold","level":"A","principle":"Operable","guideline":"2.3","guidelineTitle":"Seizures and Physical Reactions","contentText":"Web pages do not contain anything that flashes more than three times in any one second period, or the flash is below the general flash and red flash thresholds . Note Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether it is used to meet other success criteria or not) must meet this success criterion. See Conformance Requirement 5: Non-Interference ."},{"id":"three-flashes","num":"2.3.2","title":"Three Flashes","level":"AAA","principle":"Operable","guideline":"2.3","guidelineTitle":"Seizures and Physical Reactions","contentText":"Web pages do not contain anything that flashes more than three times in any one second period."},{"id":"animation-from-interactions","num":"2.3.3","title":"Animation from Interactions","level":"AAA","principle":"Operable","guideline":"2.3","guidelineTitle":"Seizures and Physical Reactions","contentText":"Motion animation triggered by interaction can be disabled, unless the animation is essential to the functionality or the information being conveyed."},{"id":"bypass-blocks","num":"2.4.1","title":"Bypass Blocks","level":"A","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"A mechanism is available to bypass blocks of content that are repeated on multiple web pages ."},{"id":"page-titled","num":"2.4.2","title":"Page Titled","level":"A","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"Web pages have titles that describe topic or purpose."},{"id":"focus-order","num":"2.4.3","title":"Focus Order","level":"A","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"If a web page can be navigated sequentially and the navigation sequences affect meaning or operation, focusable components receive focus in an order that preserves meaning and operability."},{"id":"link-purpose-in-context","num":"2.4.4","title":"Link Purpose (In Context)","level":"A","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"The purpose of each link can be determined from the link text alone or from the link text together with its programmatically determined link context , except where the purpose of the link would be ambiguous to users in general ."},{"id":"multiple-ways","num":"2.4.5","title":"Multiple Ways","level":"AA","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"More than one way is available to locate a web page within a set of web pages except where the web page is the result of, or a step in, a process ."},{"id":"headings-and-labels","num":"2.4.6","title":"Headings and Labels","level":"AA","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"Headings and labels describe topic or purpose."},{"id":"focus-visible","num":"2.4.7","title":"Focus Visible","level":"AA","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"Any keyboard operable user interface has a mode of operation where the keyboard focus indicator is visible."},{"id":"location","num":"2.4.8","title":"Location","level":"AAA","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"Information about the user's location within a set of web pages is available."},{"id":"link-purpose-link-only","num":"2.4.9","title":"Link Purpose (Link Only)","level":"AAA","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"A mechanism is available to allow the purpose of each link to be identified from link text alone, except where the purpose of the link would be ambiguous to users in general ."},{"id":"section-headings","num":"2.4.10","title":"Section Headings","level":"AAA","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"Section headings are used to organize the content. Note 1 \\"Heading\\" is used in its general sense and includes titles and other ways to add a heading to different types of content. Note 2 This success criterion covers sections within writing, not user interface components . User interface components are covered under Success Criterion 4.1.2 ."},{"id":"focus-not-obscured-minimum","num":"2.4.11","title":"Focus Not Obscured (Minimum)","level":"AA","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"When a user interface component receives keyboard focus, the component is not entirely hidden due to author-created content. Note 1 Where content in a configurable interface can be repositioned by the user, then only the initial positions of user-movable content are considered for testing and conformance of this success criterion. Note 2 Content opened by the user may obscure the component receiving focus. If the user can reveal the focused component without advancing the keyboard focus, the component with focus is not considered visually hidden due to author-created content."},{"id":"focus-not-obscured-enhanced","num":"2.4.12","title":"Focus Not Obscured (Enhanced)","level":"AAA","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"When a user interface component receives keyboard focus, no part of the component is hidden by author-created content."},{"id":"focus-appearance","num":"2.4.13","title":"Focus Appearance","level":"AAA","principle":"Operable","guideline":"2.4","guidelineTitle":"Navigable","contentText":"When the keyboard focus indicator is visible, an area of the focus indicator meets all the following: is at least as large as the area of a 2 CSS pixel thick perimeter of the unfocused component or sub-component, and has a contrast ratio of at least 3:1 between the same pixels in the focused and unfocused states. Exceptions: The focus indicator is determined by the user agent and cannot be adjusted by the author, or The focus indicator and the indicator's background color are not modified by the author. Note 1 What is perceived as the user interface component or sub-component (to determine the perimeter) depends on its visual presentation . The visual presentation includes the component's visible content , border, and component-specific background. It does not include shadow and glow effects outside the component's content, background, or border. Note 2 Examples of sub-components that may receive a focus indicator are menu items in an opened drop-down menu, or focusable cells in a grid. Note 3 Contrast calculations can be based on colors defined within the technology (such as HTML , CSS, and SVG). Pixels modified by user agent resolution enhancements and anti-aliasing can be ignored."},{"id":"pointer-gestures","num":"2.5.1","title":"Pointer Gestures","level":"A","principle":"Operable","guideline":"2.5","guidelineTitle":"Input Modalities","contentText":"All functionality that uses multipoint or path-based gestures for operation can be operated with a single pointer without a path-based gesture, unless a multipoint or path-based gesture is essential . Note This requirement applies to web content that interprets pointer actions (i.e., this does not apply to actions that are required to operate the user agent or assistive technology)."},{"id":"pointer-cancellation","num":"2.5.2","title":"Pointer Cancellation","level":"A","principle":"Operable","guideline":"2.5","guidelineTitle":"Input Modalities","contentText":"For functionality that can be operated using a single pointer , at least one of the following is true: No Down-Event The down-event of the pointer is not used to execute any part of the function; Abort or Undo Completion of the function is on the up-event , and a mechanism is available to abort the function before completion or to undo the function after completion; Up Reversal The up-event reverses any outcome of the preceding down-event; Essential Completing the function on the down-event is essential . Note 1 Functions that emulate a keyboard or numeric keypad key press are considered essential. Note 2 This requirement applies to web content that interprets pointer actions (i.e., this does not apply to actions that are required to operate the user agent or assistive technology)."},{"id":"label-in-name","num":"2.5.3","title":"Label in Name","level":"A","principle":"Operable","guideline":"2.5","guidelineTitle":"Input Modalities","contentText":"For user interface components with labels that include text or images of text , the name contains the text that is presented visually. Note A best practice is to have the text of the label at the start of the name."},{"id":"motion-actuation","num":"2.5.4","title":"Motion Actuation","level":"A","principle":"Operable","guideline":"2.5","guidelineTitle":"Input Modalities","contentText":"Functionality that can be operated by device motion or user motion can also be operated by user interface components and responding to the motion can be disabled to prevent accidental actuation, except when: Supported Interface The motion is used to operate functionality through an accessibility supported interface; Essential The motion is essential for the function and doing so would invalidate the activity."},{"id":"target-size-enhanced","num":"2.5.5","title":"Target Size (Enhanced)","level":"AAA","principle":"Operable","guideline":"2.5","guidelineTitle":"Input Modalities","contentText":"The size of the target for pointer inputs is at least 44 by 44 CSS pixels except when: Equivalent The target is available through an equivalent link or control on the same page that is at least 44 by 44 CSS pixels; Inline The target is in a sentence or block of text ; User Agent Control The size of the target is determined by the user agent and is not modified by the author; Essential A particular presentation of the target is essential to the information being conveyed."},{"id":"concurrent-input-mechanisms","num":"2.5.6","title":"Concurrent Input Mechanisms","level":"AAA","principle":"Operable","guideline":"2.5","guidelineTitle":"Input Modalities","contentText":"Web content does not restrict use of input modalities available on a platform except where the restriction is essential , required to ensure the security of the content, or required to respect user settings."},{"id":"dragging-movements","num":"2.5.7","title":"Dragging Movements","level":"AA","principle":"Operable","guideline":"2.5","guidelineTitle":"Input Modalities","contentText":"All functionality that uses a dragging movement for operation can be achieved by a single pointer without dragging, unless dragging is essential or the functionality is determined by the user agent and not modified by the author. Note This requirement applies to web content that interprets pointer actions (i.e., this does not apply to actions that are required to operate the user agent or assistive technology)."},{"id":"target-size-minimum","num":"2.5.8","title":"Target Size (Minimum)","level":"AA","principle":"Operable","guideline":"2.5","guidelineTitle":"Input Modalities","contentText":"The size of the target for pointer inputs is at least 24 by 24 CSS pixels , except when: Spacing Undersized targets (those less than 24 by 24 CSS pixels) are positioned so that if a 24 CSS pixel diameter circle is centered on the bounding box of each, the circles do not intersect another target or the circle for another undersized target; Equivalent The function can be achieved through a different control on the same page that meets this criterion; Inline The target is in a sentence or its size is otherwise constrained by the line-height of non-target text; User Agent Control The size of the target is determined by the user agent and is not modified by the author; Essential A particular presentation of the target is essential or is legally required for the information being conveyed. Note 1 Targets that allow for values to be selected spatially based on position within the target are considered one target for the purpose of the success criterion. Examples include sliders, color pickers displaying a gradient of colors, or editable areas where you position the cursor. Note 2 For inline targets the line-height should be interpreted as perpendicular to the flow of text. For example, in a language displayed vertically, the line-height would be horizontal."},{"id":"language-of-page","num":"3.1.1","title":"Language of Page","level":"A","principle":"Understandable","guideline":"3.1","guidelineTitle":"Readable","contentText":"The default human language of each web page can be programmatically determined ."},{"id":"language-of-parts","num":"3.1.2","title":"Language of Parts","level":"AA","principle":"Understandable","guideline":"3.1","guidelineTitle":"Readable","contentText":"The human language of each passage or phrase in the content can be programmatically determined except for proper names, technical terms, words of indeterminate language, and words or phrases that have become part of the vernacular of the immediately surrounding text ."},{"id":"unusual-words","num":"3.1.3","title":"Unusual Words","level":"AAA","principle":"Understandable","guideline":"3.1","guidelineTitle":"Readable","contentText":"A mechanism is available for identifying specific definitions of words or phrases used in an unusual or restricted way , including idioms and jargon ."},{"id":"abbreviations","num":"3.1.4","title":"Abbreviations","level":"AAA","principle":"Understandable","guideline":"3.1","guidelineTitle":"Readable","contentText":"A mechanism for identifying the expanded form or meaning of abbreviations is available."},{"id":"reading-level","num":"3.1.5","title":"Reading Level","level":"AAA","principle":"Understandable","guideline":"3.1","guidelineTitle":"Readable","contentText":"When text requires reading ability more advanced than the lower secondary education level after removal of proper names and titles, supplemental content , or a version that does not require reading ability more advanced than the lower secondary education level, is available."},{"id":"pronunciation","num":"3.1.6","title":"Pronunciation","level":"AAA","principle":"Understandable","guideline":"3.1","guidelineTitle":"Readable","contentText":"A mechanism is available for identifying specific pronunciation of words where meaning of the words, in context, is ambiguous without knowing the pronunciation."},{"id":"on-focus","num":"3.2.1","title":"On Focus","level":"A","principle":"Understandable","guideline":"3.2","guidelineTitle":"Predictable","contentText":"When any user interface component receives focus, it does not initiate a change of context ."},{"id":"on-input","num":"3.2.2","title":"On Input","level":"A","principle":"Understandable","guideline":"3.2","guidelineTitle":"Predictable","contentText":"Changing the setting of any user interface component does not automatically cause a change of context unless the user has been advised of the behavior before using the component."},{"id":"consistent-navigation","num":"3.2.3","title":"Consistent Navigation","level":"AA","principle":"Understandable","guideline":"3.2","guidelineTitle":"Predictable","contentText":"Navigational mechanisms that are repeated on multiple web pages within a set of web pages occur in the same relative order each time they are repeated, unless a change is initiated by the user."},{"id":"consistent-identification","num":"3.2.4","title":"Consistent Identification","level":"AA","principle":"Understandable","guideline":"3.2","guidelineTitle":"Predictable","contentText":"Components that have the same functionality within a set of web pages are identified consistently."},{"id":"change-on-request","num":"3.2.5","title":"Change on Request","level":"AAA","principle":"Understandable","guideline":"3.2","guidelineTitle":"Predictable","contentText":"Changes of context are initiated only by user request or a mechanism is available to turn off such changes."},{"id":"consistent-help","num":"3.2.6","title":"Consistent Help","level":"A","principle":"Understandable","guideline":"3.2","guidelineTitle":"Predictable","contentText":"If a web page contains any of the following help mechanisms , and those mechanisms are repeated on multiple web pages within a set of web pages , they occur in the same order relative to other page content, unless a change is initiated by the user: Human contact details; Human contact mechanism; Self-help option; A fully automated contact mechanism. Note 1 Help mechanisms may be provided directly on the page, or may be provided via a direct link to a different page containing the information. Note 2 For this success criterion, \\"the same order relative to other page content\\" can be thought of as how the content is ordered when the page is serialized. The visual position of a help mechanism is likely to be consistent across pages for the same page variation (e.g., CSS break-point). The user can initiate a change, such as changing the page's zoom or orientation, which may trigger a different page variation. This criterion is concerned with relative order across pages displayed in the same page variation (e.g., same zoom level and orientation)."},{"id":"error-identification","num":"3.3.1","title":"Error Identification","level":"A","principle":"Understandable","guideline":"3.3","guidelineTitle":"Input Assistance","contentText":"If an input error is automatically detected, the item that is in error is identified and the error is described to the user in text."},{"id":"labels-or-instructions","num":"3.3.2","title":"Labels or Instructions","level":"A","principle":"Understandable","guideline":"3.3","guidelineTitle":"Input Assistance","contentText":"Labels or instructions are provided when content requires user input."},{"id":"error-suggestion","num":"3.3.3","title":"Error Suggestion","level":"AA","principle":"Understandable","guideline":"3.3","guidelineTitle":"Input Assistance","contentText":"If an input error is automatically detected and suggestions for correction are known, then the suggestions are provided to the user, unless it would jeopardize the security or purpose of the content."},{"id":"error-prevention-legal-financial-data","num":"3.3.4","title":"Error Prevention (Legal, Financial, Data)","level":"AA","principle":"Understandable","guideline":"3.3","guidelineTitle":"Input Assistance","contentText":"For web pages that cause legal commitments or financial transactions for the user to occur, that modify or delete user-controllable data in data storage systems, or that submit user test responses, at least one of the following is true: Reversible Submissions are reversible. Checked Data entered by the user is checked for input errors and the user is provided an opportunity to correct them. Confirmed A mechanism is available for reviewing, confirming, and correcting information before finalizing the submission."},{"id":"help","num":"3.3.5","title":"Help","level":"AAA","principle":"Understandable","guideline":"3.3","guidelineTitle":"Input Assistance","contentText":"Context-sensitive help is available."},{"id":"error-prevention-all","num":"3.3.6","title":"Error Prevention (All)","level":"AAA","principle":"Understandable","guideline":"3.3","guidelineTitle":"Input Assistance","contentText":"For web pages that require the user to submit information, at least one of the following is true: Reversible Submissions are reversible. Checked Data entered by the user is checked for input errors and the user is provided an opportunity to correct them. Confirmed A mechanism is available for reviewing, confirming, and correcting information before finalizing the submission."},{"id":"redundant-entry","num":"3.3.7","title":"Redundant Entry","level":"A","principle":"Understandable","guideline":"3.3","guidelineTitle":"Input Assistance","contentText":"Information previously entered by or provided to the user that is required to be entered again in the same process is either: auto-populated, or available for the user to select. Except when: re-entering the information is essential , the information is required to ensure the security of the content, or previously entered information is no longer valid."},{"id":"accessible-authentication-minimum","num":"3.3.8","title":"Accessible Authentication (Minimum)","level":"AA","principle":"Understandable","guideline":"3.3","guidelineTitle":"Input Assistance","contentText":"A cognitive function test (such as remembering a password or solving a puzzle) is not required for any step in an authentication process unless that step provides at least one of the following: Alternative Another authentication method that does not rely on a cognitive function test. Mechanism A mechanism is available to assist the user in completing the cognitive function test. Object Recognition The cognitive function test is to recognize objects. Personal Content The cognitive function test is to identify non-text content the user provided to the website. Note 1 \\"Object recognition\\" and \\"Personal content\\" may be represented by images, video, or audio. Note 2 Examples of mechanisms that satisfy this criterion include: support for password entry by password managers to reduce memory need, and copy and paste to reduce the cognitive burden of re-typing."},{"id":"accessible-authentication-enhanced","num":"3.3.9","title":"Accessible Authentication (Enhanced)","level":"AAA","principle":"Understandable","guideline":"3.3","guidelineTitle":"Input Assistance","contentText":"A cognitive function test (such as remembering a password or solving a puzzle) is not required for any step in an authentication process unless that step provides at least one of the following: Alternative Another authentication method that does not rely on a cognitive function test. Mechanism A mechanism is available to assist the user in completing the cognitive function test."},{"id":"parsing","num":"4.1.1","title":"Parsing (Obsolete and removed)","level":"","principle":"Robust","guideline":"4.1","guidelineTitle":"Compatible","contentText":"Note This criterion was originally adopted to address problems that assistive technology had directly parsing HTML . Assistive technology no longer has any need to directly parse HTML . Consequently, these problems either no longer exist or are addressed by other criteria. This criterion no longer has utility and is removed."},{"id":"name-role-value","num":"4.1.2","title":"Name, Role, Value","level":"A","principle":"Robust","guideline":"4.1","guidelineTitle":"Compatible","contentText":"For all user interface components (including but not limited to: form elements, links and components generated by scripts), the name and role can be programmatically determined ; states , properties, and values that can be set by the user can be programmatically set ; and notification of changes to these items is available to user agents , including assistive technologies . Note This success criterion is primarily for web authors who develop or script their own user interface components. For example, standard HTML controls already meet this success criterion when used according to specification."},{"id":"status-messages","num":"4.1.3","title":"Status Messages","level":"AA","principle":"Robust","guideline":"4.1","guidelineTitle":"Compatible","contentText":"In content implemented using markup languages, status messages can be programmatically determined through role or properties such that they can be presented to the user by assistive technologies without receiving focus."}]`),o=JSON.parse(`[{"id":"non-text-content","front":"1.1.1 Non-text Content","back":{"level":"A","principle":"Perceivable","guideline":"1.1 Text Alternatives","text":"All non-text content that is presented to the user has a text alternative that serves the equivalent purpose, except for the situations listed below. Controls, Input If non-text content is a control or accepts user input, then it has a name that describes its purpose. (Refer to Success Criterion 4.1.2 for additional requirements for controls and content that accepts user input.) Time-Based Media If non-text content is time-based media, then text alternatives at least provide descriptive identification of the non-text content. (Refer to Guideline 1.2 for additional requirements for media.) Test If non-text content is a test or exercise that would be invalid if presented in text , then text alternatives at least provide descriptive identification of the non-text content. Sensory If non-text content is primarily intended to create a specific sensory experience , then text alternatives at least provide descriptive identification of the non-text content. CAPTCHA If the purpose of non-text content is to confirm that content is being accessed by a person rather than a computer, then text alternatives that identify and describe the purpose of the non-text content are provided, and alternative forms of CAPTCHA using output modes for different types of sensory perception are provided to accommodate different disabilities. Decoration, Formatting, Invisible If non-text content is pure decoration , is used only for visual formatting, or is not presented to users, then it is implemented in a way that it can be ignored by assistive technology ."}},{"id":"audio-only-and-video-only-prerecorded","front":"1.2.1 Audio-only and Video-only (Prerecorded)","back":{"level":"A","principle":"Perceivable","guideline":"1.2 Time-based Media","text":"For prerecorded audio-only and prerecorded video-only media, the following are true, except when the audio or video is a media alternative for text and is clearly labeled as such: Prerecorded Audio-only An alternative for time-based media is provided that presents equivalent information for prerecorded audio-only content. Prerecorded Video-only Either an alternative for time-based media or an audio track is provided that presents equivalent information for prerecorded video-only content."}},{"id":"captions-prerecorded","front":"1.2.2 Captions (Prerecorded)","back":{"level":"A","principle":"Perceivable","guideline":"1.2 Time-based Media","text":"Captions are provided for all prerecorded audio content in synchronized media , except when the media is a media alternative for text and is clearly labeled as such."}},{"id":"audio-description-or-media-alternative-prerecorded","front":"1.2.3 Audio Description or Media Alternative (Prerecorded)","back":{"level":"A","principle":"Perceivable","guideline":"1.2 Time-based Media","text":"An alternative for time-based media or audio description of the prerecorded video content is provided for synchronized media , except when the media is a media alternative for text and is clearly labeled as such."}},{"id":"captions-live","front":"1.2.4 Captions (Live)","back":{"level":"AA","principle":"Perceivable","guideline":"1.2 Time-based Media","text":"Captions are provided for all live audio content in synchronized media ."}},{"id":"audio-description-prerecorded","front":"1.2.5 Audio Description (Prerecorded)","back":{"level":"AA","principle":"Perceivable","guideline":"1.2 Time-based Media","text":"Audio description is provided for all prerecorded video content in synchronized media ."}},{"id":"sign-language-prerecorded","front":"1.2.6 Sign Language (Prerecorded)","back":{"level":"AAA","principle":"Perceivable","guideline":"1.2 Time-based Media","text":"Sign language interpretation is provided for all prerecorded audio content in synchronized media ."}},{"id":"extended-audio-description-prerecorded","front":"1.2.7 Extended Audio Description (Prerecorded)","back":{"level":"AAA","principle":"Perceivable","guideline":"1.2 Time-based Media","text":"Where pauses in foreground audio are insufficient to allow audio descriptions to convey the sense of the video, extended audio description is provided for all prerecorded video content in synchronized media ."}},{"id":"media-alternative-prerecorded","front":"1.2.8 Media Alternative (Prerecorded)","back":{"level":"AAA","principle":"Perceivable","guideline":"1.2 Time-based Media","text":"An alternative for time-based media is provided for all prerecorded synchronized media and for all prerecorded video-only media."}},{"id":"audio-only-live","front":"1.2.9 Audio-only (Live)","back":{"level":"AAA","principle":"Perceivable","guideline":"1.2 Time-based Media","text":"An alternative for time-based media that presents equivalent information for live audio-only content is provided."}},{"id":"info-and-relationships","front":"1.3.1 Info and Relationships","back":{"level":"A","principle":"Perceivable","guideline":"1.3 Adaptable","text":"Information, structure , and relationships conveyed through presentation can be programmatically determined or are available in text."}},{"id":"meaningful-sequence","front":"1.3.2 Meaningful Sequence","back":{"level":"A","principle":"Perceivable","guideline":"1.3 Adaptable","text":"When the sequence in which content is presented affects its meaning, a correct reading sequence can be programmatically determined ."}},{"id":"sensory-characteristics","front":"1.3.3 Sensory Characteristics","back":{"level":"A","principle":"Perceivable","guideline":"1.3 Adaptable","text":"Instructions provided for understanding and operating content do not rely solely on sensory characteristics of components such as shape, color, size, visual location, orientation, or sound. Note For requirements related to color, refer to Guideline 1.4 ."}},{"id":"orientation","front":"1.3.4 Orientation","back":{"level":"AA","principle":"Perceivable","guideline":"1.3 Adaptable","text":"Content does not restrict its view and operation to a single display orientation, such as portrait or landscape, unless a specific display orientation is essential . Note Examples where a particular display orientation may be essential are a bank check, a piano application, slides for a projector or television, or virtual reality content where content is not necessarily restricted to landscape or portrait display orientation."}},{"id":"identify-input-purpose","front":"1.3.5 Identify Input Purpose","back":{"level":"AA","principle":"Perceivable","guideline":"1.3 Adaptable","text":"The purpose of each input field collecting information about the user can be programmatically determined when: The input field serves a purpose identified in the Input Purposes for user interface components section ; and The content is implemented using technologies with support for identifying the expected meaning for form input data."}},{"id":"identify-purpose","front":"1.3.6 Identify Purpose","back":{"level":"AAA","principle":"Perceivable","guideline":"1.3 Adaptable","text":"In content implemented using markup languages, the purpose of user interface components , icons, and regions can be programmatically determined ."}},{"id":"use-of-color","front":"1.4.1 Use of Color","back":{"level":"A","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"Color is not used as the only visual means of conveying information, indicating an action, prompting a response, or distinguishing a visual element. Note This success criterion addresses color perception specifically. Other forms of perception are covered in Guideline 1.3 including programmatic access to color and other visual presentation coding."}},{"id":"audio-control","front":"1.4.2 Audio Control","back":{"level":"A","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"If any audio on a web page plays automatically for more than 3 seconds, either a mechanism is available to pause or stop the audio, or a mechanism is available to control audio volume independently from the overall system volume level. Note Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether or not it is used to meet other success criteria) must meet this success criterion. See Conformance Requirement 5: Non-Interference ."}},{"id":"contrast-minimum","front":"1.4.3 Contrast (Minimum)","back":{"level":"AA","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"The visual presentation of text and images of text has a contrast ratio of at least 4.5:1, except for the following: Large Text Large-scale text and images of large-scale text have a contrast ratio of at least 3:1; Incidental Text or images of text that are part of an inactive user interface component , that are pure decoration , that are not visible to anyone, or that are part of a picture that contains significant other visual content, have no contrast requirement. Logotypes Text that is part of a logo or brand name has no contrast requirement."}},{"id":"resize-text","front":"1.4.4 Resize Text","back":{"level":"AA","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"Except for captions and images of text , text can be resized without assistive technology up to 200 percent without loss of content or functionality."}},{"id":"images-of-text","front":"1.4.5 Images of Text","back":{"level":"AA","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"If the technologies being used can achieve the visual presentation, text is used to convey information rather than images of text except for the following: Customizable The image of text can be visually customized to the user's requirements; Essential A particular presentation of text is essential to the information being conveyed. Note Logotypes (text that is part of a logo or brand name) are considered essential."}},{"id":"contrast-enhanced","front":"1.4.6 Contrast (Enhanced)","back":{"level":"AAA","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"The visual presentation of text and images of text has a contrast ratio of at least 7:1, except for the following: Large Text Large-scale text and images of large-scale text have a contrast ratio of at least 4.5:1; Incidental Text or images of text that are part of an inactive user interface component , that are pure decoration , that are not visible to anyone, or that are part of a picture that contains significant other visual content, have no contrast requirement. Logotypes Text that is part of a logo or brand name has no contrast requirement."}},{"id":"low-or-no-background-audio","front":"1.4.7 Low or No Background Audio","back":{"level":"AAA","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"For prerecorded audio-only content that (1) contains primarily speech in the foreground, (2) is not an audio CAPTCHA or audio logo, and (3) is not vocalization intended to be primarily musical expression such as singing or rapping, at least one of the following is true: No Background The audio does not contain background sounds. Turn Off The background sounds can be turned off. 20 dB The background sounds are at least 20 decibels lower than the foreground speech content, with the exception of occasional sounds that last for only one or two seconds. Note Per the definition of \\"decibel,\\" background sound that meets this requirement will be approximately four times quieter than the foreground speech content."}},{"id":"visual-presentation","front":"1.4.8 Visual Presentation","back":{"level":"AAA","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"For the visual presentation of blocks of text , a mechanism is available to achieve the following: Foreground and background colors can be selected by the user. Width is no more than 80 characters or glyphs (40 if CJK). Text is not justified (aligned to both the left and the right margins). Line spacing (leading) is at least space-and-a-half within paragraphs, and paragraph spacing is at least 1.5 times larger than the line spacing. Text can be resized without assistive technology up to 200 percent in a way that does not require the user to scroll horizontally to read a line of text on a full-screen window . Note 1 Content is not required to use these values. The requirement is that a mechanism is available for users to change these presentation aspects. The mechanism can be provided by the browser or other user agent. Content is not required to provide the mechanism. Note 2 Writing systems for some languages use different presentation aspects to improve readability and legibility. If a presentation aspect in this success criterion is not used in a writing system, content in that writing system does not need to use that presentation setting and can conform without it. Authors are encouraged to follow guidance for improving readability and legibility of text in their writing system."}},{"id":"images-of-text-no-exception","front":"1.4.9 Images of Text (No Exception)","back":{"level":"AAA","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"Images of text are only used for pure decoration or where a particular presentation of text is essential to the information being conveyed. Note Logotypes (text that is part of a logo or brand name) are considered essential."}},{"id":"reflow","front":"1.4.10 Reflow","back":{"level":"AA","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"Content can be presented without loss of information or functionality, and without requiring scrolling in two dimensions for: Vertical scrolling content at a width equivalent to 320 CSS pixels ; Horizontal scrolling content at a height equivalent to 256 CSS pixels . Except for parts of the content which require two-dimensional layout for usage or meaning. Note 1 320 CSS pixels is equivalent to a starting viewport width of 1280 CSS pixels wide at 400% zoom. For web content which is designed to scroll horizontally (e.g., with vertical text), 256 CSS pixels is equivalent to a starting viewport height of 1024 CSS pixels at 400% zoom. Note 2 Examples of content which requires two-dimensional layout are images required for understanding (such as maps and diagrams), video, games, presentations, data tables (not individual cells), and interfaces where it is necessary to keep toolbars in view while manipulating content. It is acceptable to provide two-dimensional scrolling for such parts of the content."}},{"id":"non-text-contrast","front":"1.4.11 Non-text Contrast","back":{"level":"AA","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"The visual presentation of the following have a contrast ratio of at least 3:1 against adjacent color(s): User Interface Components Visual information required to identify user interface components and states , except for inactive components or where the appearance of the component is determined by the user agent and not modified by the author; Graphical Objects Parts of graphics required to understand the content, except when a particular presentation of graphics is essential to the information being conveyed."}},{"id":"text-spacing","front":"1.4.12 Text Spacing","back":{"level":"AA","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"In content implemented using markup languages that support the following text style properties , no loss of content or functionality occurs by setting all of the following and by changing no other style property: Line height (line spacing) to at least 1.5 times the font size; Spacing following paragraphs to at least 2 times the font size; Letter spacing (tracking) to at least 0.12 times the font size; Word spacing to at least 0.16 times the font size. Exception: Human languages and scripts that do not make use of one or more of these text style properties in written text can conform using only the properties that exist for that combination of language and script. Note 1 Content is not required to use these text spacing values. The requirement is to ensure that when a user overrides the authored text spacing, content or functionality is not lost. Note 2 Writing systems for some languages use different text spacing settings, such as paragraph start indent. Authors are encouraged to follow locally available guidance for improving readability and legibility of text in their writing system."}},{"id":"content-on-hover-or-focus","front":"1.4.13 Content on Hover or Focus","back":{"level":"AA","principle":"Perceivable","guideline":"1.4 Distinguishable","text":"Where receiving and then removing pointer hover or keyboard focus triggers additional content to become visible and then hidden, the following are true: Dismissible A mechanism is available to dismiss the additional content without moving pointer hover or keyboard focus, unless the additional content communicates an input error or does not obscure or replace other content; Hoverable If pointer hover can trigger the additional content, then the pointer can be moved over the additional content without the additional content disappearing; Persistent The additional content remains visible until the hover or focus trigger is removed, the user dismisses it, or its information is no longer valid. Exception: The visual presentation of the additional content is controlled by the user agent and is not modified by the author. Note 1 Examples of additional content controlled by the user agent include browser tooltips created through use of the HTML title attribute [ HTML ]. Note 2 Custom tooltips, sub-menus, and other nonmodal popups that display on hover and focus are examples of additional content covered by this criterion. Note 3 This criterion applies to content that appears in addition to the triggering component itself. Since hidden components that are made visible on keyboard focus (such as links used to skip to another part of a page) do not present additional content they are not covered by this criterion."}},{"id":"keyboard","front":"2.1.1 Keyboard","back":{"level":"A","principle":"Operable","guideline":"2.1 Keyboard Accessible","text":"All functionality of the content is operable through a keyboard interface without requiring specific timings for individual keystrokes, except where the underlying function requires input that depends on the path of the user's movement and not just the endpoints. Note 1 This exception relates to the underlying function, not the input technique. For example, if using handwriting to enter text, the input technique (handwriting) requires path-dependent input but the underlying function (text input) does not. Note 2 This does not forbid and should not discourage providing mouse input or other input methods in addition to keyboard operation."}},{"id":"no-keyboard-trap","front":"2.1.2 No Keyboard Trap","back":{"level":"A","principle":"Operable","guideline":"2.1 Keyboard Accessible","text":"If keyboard focus can be moved to a component of the page using a keyboard interface , then focus can be moved away from that component using only a keyboard interface, and, if it requires more than unmodified arrow or tab keys or other standard exit methods, the user is advised of the method for moving focus away. Note Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether it is used to meet other success criteria or not) must meet this success criterion. See Conformance Requirement 5: Non-Interference ."}},{"id":"keyboard-no-exception","front":"2.1.3 Keyboard (No Exception)","back":{"level":"AAA","principle":"Operable","guideline":"2.1 Keyboard Accessible","text":"All functionality of the content is operable through a keyboard interface without requiring specific timings for individual keystrokes."}},{"id":"character-key-shortcuts","front":"2.1.4 Character Key Shortcuts","back":{"level":"A","principle":"Operable","guideline":"2.1 Keyboard Accessible","text":"If a keyboard shortcut is implemented in content using only letter (including upper- and lower-case letters), punctuation, number, or symbol characters, then at least one of the following is true: Turn off A mechanism is available to turn the shortcut off; Remap A mechanism is available to remap the shortcut to include one or more non-printable keyboard keys (e.g., Ctrl, Alt); Active only on focus The keyboard shortcut for a user interface component is only active when that component has focus."}},{"id":"timing-adjustable","front":"2.2.1 Timing Adjustable","back":{"level":"A","principle":"Operable","guideline":"2.2 Enough Time","text":"For each time limit that is set by the content, at least one of the following is true: Turn off The user is allowed to turn off the time limit before encountering it; or Adjust The user is allowed to adjust the time limit before encountering it over a wide range that is at least ten times the length of the default setting; or Extend The user is warned before time expires and given at least 20 seconds to extend the time limit with a simple action (for example, \\"press the space bar\\"), and the user is allowed to extend the time limit at least ten times; or Real-time Exception The time limit is a required part of a real-time event (for example, an auction), and no alternative to the time limit is possible; or Essential Exception The time limit is essential and extending it would invalidate the activity; or 20 Hour Exception The time limit is longer than 20 hours. Note This success criterion helps ensure that users can complete tasks without unexpected changes in content or context that are a result of a time limit. This success criterion should be considered in conjunction with Success Criterion 3.2.1 , which puts limits on changes of content or context as a result of user action."}},{"id":"pause-stop-hide","front":"2.2.2 Pause, Stop, Hide","back":{"level":"A","principle":"Operable","guideline":"2.2 Enough Time","text":"For moving, blinking , scrolling, or auto-updating information, all of the following are true: Moving, blinking, scrolling For any moving, blinking or scrolling information that (1) starts automatically, (2) lasts more than five seconds, and (3) is presented in parallel with other content, there is a mechanism for the user to pause , stop, or hide it unless the movement, blinking, or scrolling is part of an activity where it is essential ; and Auto-updating For any auto-updating information that (1) starts automatically and (2) is presented in parallel with other content, there is a mechanism for the user to pause, stop, or hide it or to control the frequency of the update unless the auto-updating is part of an activity where it is essential. Note 1 For requirements related to flickering or flashing content, refer to Guideline 2.3 . Note 2 Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether it is used to meet other success criteria or not) must meet this success criterion. See Conformance Requirement 5: Non-Interference . Note 3 Content that is updated periodically by software or that is streamed to the user agent is not required to preserve or present information that is generated or received between the initiation of the pause and resuming presentation, as this may not be technically possible, and in many situations could be misleading to do so. Note 4 An animation that occurs as part of a preload phase or similar situation can be considered essential if interaction cannot occur during that phase for all users and if not indicating progress could confuse users or cause them to think that content was frozen or broken."}},{"id":"no-timing","front":"2.2.3 No Timing","back":{"level":"AAA","principle":"Operable","guideline":"2.2 Enough Time","text":"Timing is not an essential part of the event or activity presented by the content, except for non-interactive synchronized media and real-time events ."}},{"id":"interruptions","front":"2.2.4 Interruptions","back":{"level":"AAA","principle":"Operable","guideline":"2.2 Enough Time","text":"Interruptions can be postponed or suppressed by the user, except interruptions involving an emergency ."}},{"id":"re-authenticating","front":"2.2.5 Re-authenticating","back":{"level":"AAA","principle":"Operable","guideline":"2.2 Enough Time","text":"When an authenticated session expires, the user can continue the activity without loss of data after re-authenticating."}},{"id":"timeouts","front":"2.2.6 Timeouts","back":{"level":"AAA","principle":"Operable","guideline":"2.2 Enough Time","text":"Users are warned of the duration of any user inactivity that could cause data loss, unless the data is preserved for more than 20 hours when the user does not take any actions. Note Privacy regulations may require explicit user consent before user identification has been authenticated and before user data is preserved. In cases where the user is a minor, explicit consent may not be solicited in most jurisdictions, countries or regions. Consultation with privacy professionals and legal counsel is advised when considering data preservation as an approach to satisfy this success criterion."}},{"id":"three-flashes-or-below-threshold","front":"2.3.1 Three Flashes or Below Threshold","back":{"level":"A","principle":"Operable","guideline":"2.3 Seizures and Physical Reactions","text":"Web pages do not contain anything that flashes more than three times in any one second period, or the flash is below the general flash and red flash thresholds . Note Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether it is used to meet other success criteria or not) must meet this success criterion. See Conformance Requirement 5: Non-Interference ."}},{"id":"three-flashes","front":"2.3.2 Three Flashes","back":{"level":"AAA","principle":"Operable","guideline":"2.3 Seizures and Physical Reactions","text":"Web pages do not contain anything that flashes more than three times in any one second period."}},{"id":"animation-from-interactions","front":"2.3.3 Animation from Interactions","back":{"level":"AAA","principle":"Operable","guideline":"2.3 Seizures and Physical Reactions","text":"Motion animation triggered by interaction can be disabled, unless the animation is essential to the functionality or the information being conveyed."}},{"id":"bypass-blocks","front":"2.4.1 Bypass Blocks","back":{"level":"A","principle":"Operable","guideline":"2.4 Navigable","text":"A mechanism is available to bypass blocks of content that are repeated on multiple web pages ."}},{"id":"page-titled","front":"2.4.2 Page Titled","back":{"level":"A","principle":"Operable","guideline":"2.4 Navigable","text":"Web pages have titles that describe topic or purpose."}},{"id":"focus-order","front":"2.4.3 Focus Order","back":{"level":"A","principle":"Operable","guideline":"2.4 Navigable","text":"If a web page can be navigated sequentially and the navigation sequences affect meaning or operation, focusable components receive focus in an order that preserves meaning and operability."}},{"id":"link-purpose-in-context","front":"2.4.4 Link Purpose (In Context)","back":{"level":"A","principle":"Operable","guideline":"2.4 Navigable","text":"The purpose of each link can be determined from the link text alone or from the link text together with its programmatically determined link context , except where the purpose of the link would be ambiguous to users in general ."}},{"id":"multiple-ways","front":"2.4.5 Multiple Ways","back":{"level":"AA","principle":"Operable","guideline":"2.4 Navigable","text":"More than one way is available to locate a web page within a set of web pages except where the web page is the result of, or a step in, a process ."}},{"id":"headings-and-labels","front":"2.4.6 Headings and Labels","back":{"level":"AA","principle":"Operable","guideline":"2.4 Navigable","text":"Headings and labels describe topic or purpose."}},{"id":"focus-visible","front":"2.4.7 Focus Visible","back":{"level":"AA","principle":"Operable","guideline":"2.4 Navigable","text":"Any keyboard operable user interface has a mode of operation where the keyboard focus indicator is visible."}},{"id":"location","front":"2.4.8 Location","back":{"level":"AAA","principle":"Operable","guideline":"2.4 Navigable","text":"Information about the user's location within a set of web pages is available."}},{"id":"link-purpose-link-only","front":"2.4.9 Link Purpose (Link Only)","back":{"level":"AAA","principle":"Operable","guideline":"2.4 Navigable","text":"A mechanism is available to allow the purpose of each link to be identified from link text alone, except where the purpose of the link would be ambiguous to users in general ."}},{"id":"section-headings","front":"2.4.10 Section Headings","back":{"level":"AAA","principle":"Operable","guideline":"2.4 Navigable","text":"Section headings are used to organize the content. Note 1 \\"Heading\\" is used in its general sense and includes titles and other ways to add a heading to different types of content. Note 2 This success criterion covers sections within writing, not user interface components . User interface components are covered under Success Criterion 4.1.2 ."}},{"id":"focus-not-obscured-minimum","front":"2.4.11 Focus Not Obscured (Minimum)","back":{"level":"AA","principle":"Operable","guideline":"2.4 Navigable","text":"When a user interface component receives keyboard focus, the component is not entirely hidden due to author-created content. Note 1 Where content in a configurable interface can be repositioned by the user, then only the initial positions of user-movable content are considered for testing and conformance of this success criterion. Note 2 Content opened by the user may obscure the component receiving focus. If the user can reveal the focused component without advancing the keyboard focus, the component with focus is not considered visually hidden due to author-created content."}},{"id":"focus-not-obscured-enhanced","front":"2.4.12 Focus Not Obscured (Enhanced)","back":{"level":"AAA","principle":"Operable","guideline":"2.4 Navigable","text":"When a user interface component receives keyboard focus, no part of the component is hidden by author-created content."}},{"id":"focus-appearance","front":"2.4.13 Focus Appearance","back":{"level":"AAA","principle":"Operable","guideline":"2.4 Navigable","text":"When the keyboard focus indicator is visible, an area of the focus indicator meets all the following: is at least as large as the area of a 2 CSS pixel thick perimeter of the unfocused component or sub-component, and has a contrast ratio of at least 3:1 between the same pixels in the focused and unfocused states. Exceptions: The focus indicator is determined by the user agent and cannot be adjusted by the author, or The focus indicator and the indicator's background color are not modified by the author. Note 1 What is perceived as the user interface component or sub-component (to determine the perimeter) depends on its visual presentation . The visual presentation includes the component's visible content , border, and component-specific background. It does not include shadow and glow effects outside the component's content, background, or border. Note 2 Examples of sub-components that may receive a focus indicator are menu items in an opened drop-down menu, or focusable cells in a grid. Note 3 Contrast calculations can be based on colors defined within the technology (such as HTML , CSS, and SVG). Pixels modified by user agent resolution enhancements and anti-aliasing can be ignored."}},{"id":"pointer-gestures","front":"2.5.1 Pointer Gestures","back":{"level":"A","principle":"Operable","guideline":"2.5 Input Modalities","text":"All functionality that uses multipoint or path-based gestures for operation can be operated with a single pointer without a path-based gesture, unless a multipoint or path-based gesture is essential . Note This requirement applies to web content that interprets pointer actions (i.e., this does not apply to actions that are required to operate the user agent or assistive technology)."}},{"id":"pointer-cancellation","front":"2.5.2 Pointer Cancellation","back":{"level":"A","principle":"Operable","guideline":"2.5 Input Modalities","text":"For functionality that can be operated using a single pointer , at least one of the following is true: No Down-Event The down-event of the pointer is not used to execute any part of the function; Abort or Undo Completion of the function is on the up-event , and a mechanism is available to abort the function before completion or to undo the function after completion; Up Reversal The up-event reverses any outcome of the preceding down-event; Essential Completing the function on the down-event is essential . Note 1 Functions that emulate a keyboard or numeric keypad key press are considered essential. Note 2 This requirement applies to web content that interprets pointer actions (i.e., this does not apply to actions that are required to operate the user agent or assistive technology)."}},{"id":"label-in-name","front":"2.5.3 Label in Name","back":{"level":"A","principle":"Operable","guideline":"2.5 Input Modalities","text":"For user interface components with labels that include text or images of text , the name contains the text that is presented visually. Note A best practice is to have the text of the label at the start of the name."}},{"id":"motion-actuation","front":"2.5.4 Motion Actuation","back":{"level":"A","principle":"Operable","guideline":"2.5 Input Modalities","text":"Functionality that can be operated by device motion or user motion can also be operated by user interface components and responding to the motion can be disabled to prevent accidental actuation, except when: Supported Interface The motion is used to operate functionality through an accessibility supported interface; Essential The motion is essential for the function and doing so would invalidate the activity."}},{"id":"target-size-enhanced","front":"2.5.5 Target Size (Enhanced)","back":{"level":"AAA","principle":"Operable","guideline":"2.5 Input Modalities","text":"The size of the target for pointer inputs is at least 44 by 44 CSS pixels except when: Equivalent The target is available through an equivalent link or control on the same page that is at least 44 by 44 CSS pixels; Inline The target is in a sentence or block of text ; User Agent Control The size of the target is determined by the user agent and is not modified by the author; Essential A particular presentation of the target is essential to the information being conveyed."}},{"id":"concurrent-input-mechanisms","front":"2.5.6 Concurrent Input Mechanisms","back":{"level":"AAA","principle":"Operable","guideline":"2.5 Input Modalities","text":"Web content does not restrict use of input modalities available on a platform except where the restriction is essential , required to ensure the security of the content, or required to respect user settings."}},{"id":"dragging-movements","front":"2.5.7 Dragging Movements","back":{"level":"AA","principle":"Operable","guideline":"2.5 Input Modalities","text":"All functionality that uses a dragging movement for operation can be achieved by a single pointer without dragging, unless dragging is essential or the functionality is determined by the user agent and not modified by the author. Note This requirement applies to web content that interprets pointer actions (i.e., this does not apply to actions that are required to operate the user agent or assistive technology)."}},{"id":"target-size-minimum","front":"2.5.8 Target Size (Minimum)","back":{"level":"AA","principle":"Operable","guideline":"2.5 Input Modalities","text":"The size of the target for pointer inputs is at least 24 by 24 CSS pixels , except when: Spacing Undersized targets (those less than 24 by 24 CSS pixels) are positioned so that if a 24 CSS pixel diameter circle is centered on the bounding box of each, the circles do not intersect another target or the circle for another undersized target; Equivalent The function can be achieved through a different control on the same page that meets this criterion; Inline The target is in a sentence or its size is otherwise constrained by the line-height of non-target text; User Agent Control The size of the target is determined by the user agent and is not modified by the author; Essential A particular presentation of the target is essential or is legally required for the information being conveyed. Note 1 Targets that allow for values to be selected spatially based on position within the target are considered one target for the purpose of the success criterion. Examples include sliders, color pickers displaying a gradient of colors, or editable areas where you position the cursor. Note 2 For inline targets the line-height should be interpreted as perpendicular to the flow of text. For example, in a language displayed vertically, the line-height would be horizontal."}},{"id":"language-of-page","front":"3.1.1 Language of Page","back":{"level":"A","principle":"Understandable","guideline":"3.1 Readable","text":"The default human language of each web page can be programmatically determined ."}},{"id":"language-of-parts","front":"3.1.2 Language of Parts","back":{"level":"AA","principle":"Understandable","guideline":"3.1 Readable","text":"The human language of each passage or phrase in the content can be programmatically determined except for proper names, technical terms, words of indeterminate language, and words or phrases that have become part of the vernacular of the immediately surrounding text ."}},{"id":"unusual-words","front":"3.1.3 Unusual Words","back":{"level":"AAA","principle":"Understandable","guideline":"3.1 Readable","text":"A mechanism is available for identifying specific definitions of words or phrases used in an unusual or restricted way , including idioms and jargon ."}},{"id":"abbreviations","front":"3.1.4 Abbreviations","back":{"level":"AAA","principle":"Understandable","guideline":"3.1 Readable","text":"A mechanism for identifying the expanded form or meaning of abbreviations is available."}},{"id":"reading-level","front":"3.1.5 Reading Level","back":{"level":"AAA","principle":"Understandable","guideline":"3.1 Readable","text":"When text requires reading ability more advanced than the lower secondary education level after removal of proper names and titles, supplemental content , or a version that does not require reading ability more advanced than the lower secondary education level, is available."}},{"id":"pronunciation","front":"3.1.6 Pronunciation","back":{"level":"AAA","principle":"Understandable","guideline":"3.1 Readable","text":"A mechanism is available for identifying specific pronunciation of words where meaning of the words, in context, is ambiguous without knowing the pronunciation."}},{"id":"on-focus","front":"3.2.1 On Focus","back":{"level":"A","principle":"Understandable","guideline":"3.2 Predictable","text":"When any user interface component receives focus, it does not initiate a change of context ."}},{"id":"on-input","front":"3.2.2 On Input","back":{"level":"A","principle":"Understandable","guideline":"3.2 Predictable","text":"Changing the setting of any user interface component does not automatically cause a change of context unless the user has been advised of the behavior before using the component."}},{"id":"consistent-navigation","front":"3.2.3 Consistent Navigation","back":{"level":"AA","principle":"Understandable","guideline":"3.2 Predictable","text":"Navigational mechanisms that are repeated on multiple web pages within a set of web pages occur in the same relative order each time they are repeated, unless a change is initiated by the user."}},{"id":"consistent-identification","front":"3.2.4 Consistent Identification","back":{"level":"AA","principle":"Understandable","guideline":"3.2 Predictable","text":"Components that have the same functionality within a set of web pages are identified consistently."}},{"id":"change-on-request","front":"3.2.5 Change on Request","back":{"level":"AAA","principle":"Understandable","guideline":"3.2 Predictable","text":"Changes of context are initiated only by user request or a mechanism is available to turn off such changes."}},{"id":"consistent-help","front":"3.2.6 Consistent Help","back":{"level":"A","principle":"Understandable","guideline":"3.2 Predictable","text":"If a web page contains any of the following help mechanisms , and those mechanisms are repeated on multiple web pages within a set of web pages , they occur in the same order relative to other page content, unless a change is initiated by the user: Human contact details; Human contact mechanism; Self-help option; A fully automated contact mechanism. Note 1 Help mechanisms may be provided directly on the page, or may be provided via a direct link to a different page containing the information. Note 2 For this success criterion, \\"the same order relative to other page content\\" can be thought of as how the content is ordered when the page is serialized. The visual position of a help mechanism is likely to be consistent across pages for the same page variation (e.g., CSS break-point). The user can initiate a change, such as changing the page's zoom or orientation, which may trigger a different page variation. This criterion is concerned with relative order across pages displayed in the same page variation (e.g., same zoom level and orientation)."}},{"id":"error-identification","front":"3.3.1 Error Identification","back":{"level":"A","principle":"Understandable","guideline":"3.3 Input Assistance","text":"If an input error is automatically detected, the item that is in error is identified and the error is described to the user in text."}},{"id":"labels-or-instructions","front":"3.3.2 Labels or Instructions","back":{"level":"A","principle":"Understandable","guideline":"3.3 Input Assistance","text":"Labels or instructions are provided when content requires user input."}},{"id":"error-suggestion","front":"3.3.3 Error Suggestion","back":{"level":"AA","principle":"Understandable","guideline":"3.3 Input Assistance","text":"If an input error is automatically detected and suggestions for correction are known, then the suggestions are provided to the user, unless it would jeopardize the security or purpose of the content."}},{"id":"error-prevention-legal-financial-data","front":"3.3.4 Error Prevention (Legal, Financial, Data)","back":{"level":"AA","principle":"Understandable","guideline":"3.3 Input Assistance","text":"For web pages that cause legal commitments or financial transactions for the user to occur, that modify or delete user-controllable data in data storage systems, or that submit user test responses, at least one of the following is true: Reversible Submissions are reversible. Checked Data entered by the user is checked for input errors and the user is provided an opportunity to correct them. Confirmed A mechanism is available for reviewing, confirming, and correcting information before finalizing the submission."}},{"id":"help","front":"3.3.5 Help","back":{"level":"AAA","principle":"Understandable","guideline":"3.3 Input Assistance","text":"Context-sensitive help is available."}},{"id":"error-prevention-all","front":"3.3.6 Error Prevention (All)","back":{"level":"AAA","principle":"Understandable","guideline":"3.3 Input Assistance","text":"For web pages that require the user to submit information, at least one of the following is true: Reversible Submissions are reversible. Checked Data entered by the user is checked for input errors and the user is provided an opportunity to correct them. Confirmed A mechanism is available for reviewing, confirming, and correcting information before finalizing the submission."}},{"id":"redundant-entry","front":"3.3.7 Redundant Entry","back":{"level":"A","principle":"Understandable","guideline":"3.3 Input Assistance","text":"Information previously entered by or provided to the user that is required to be entered again in the same process is either: auto-populated, or available for the user to select. Except when: re-entering the information is essential , the information is required to ensure the security of the content, or previously entered information is no longer valid."}},{"id":"accessible-authentication-minimum","front":"3.3.8 Accessible Authentication (Minimum)","back":{"level":"AA","principle":"Understandable","guideline":"3.3 Input Assistance","text":"A cognitive function test (such as remembering a password or solving a puzzle) is not required for any step in an authentication process unless that step provides at least one of the following: Alternative Another authentication method that does not rely on a cognitive function test. Mechanism A mechanism is available to assist the user in completing the cognitive function test. Object Recognition The cognitive function test is to recognize objects. Personal Content The cognitive function test is to identify non-text content the user provided to the website. Note 1 \\"Object recognition\\" and \\"Personal content\\" may be represented by images, video, or audio. Note 2 Examples of mechanisms that satisfy this criterion include: support for password entry by password managers to reduce memory need, and copy and paste to reduce the cognitive burden of re-typing."}},{"id":"accessible-authentication-enhanced","front":"3.3.9 Accessible Authentication (Enhanced)","back":{"level":"AAA","principle":"Understandable","guideline":"3.3 Input Assistance","text":"A cognitive function test (such as remembering a password or solving a puzzle) is not required for any step in an authentication process unless that step provides at least one of the following: Alternative Another authentication method that does not rely on a cognitive function test. Mechanism A mechanism is available to assist the user in completing the cognitive function test."}},{"id":"parsing","front":"4.1.1 Parsing (Obsolete and removed)","back":{"level":"","principle":"Robust","guideline":"4.1 Compatible","text":"Note This criterion was originally adopted to address problems that assistive technology had directly parsing HTML . Assistive technology no longer has any need to directly parse HTML . Consequently, these problems either no longer exist or are addressed by other criteria. This criterion no longer has utility and is removed."}},{"id":"name-role-value","front":"4.1.2 Name, Role, Value","back":{"level":"A","principle":"Robust","guideline":"4.1 Compatible","text":"For all user interface components (including but not limited to: form elements, links and components generated by scripts), the name and role can be programmatically determined ; states , properties, and values that can be set by the user can be programmatically set ; and notification of changes to these items is available to user agents , including assistive technologies . Note This success criterion is primarily for web authors who develop or script their own user interface components. For example, standard HTML controls already meet this success criterion when used according to specification."}},{"id":"status-messages","front":"4.1.3 Status Messages","back":{"level":"AA","principle":"Robust","guideline":"4.1 Compatible","text":"In content implemented using markup languages, status messages can be programmatically determined through role or properties such that they can be presented to the user by assistive technologies without receiving focus."}}]`),a=JSON.parse(`[{"id":"sc-title-non-text-content","type":"mcq","skill":"recognition","scId":"non-text-content","prompt":"Which success criterion matches: Non-text Content?","answer":"1.1.1","choices":["1.1.1","1.2.1","1.2.2","1.2.3"]},{"id":"sc-level-non-text-content","type":"mcq","skill":"classification","scId":"non-text-content","prompt":"What conformance level is 1.1.1 Non-text Content?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-non-text-content","type":"mcq","skill":"classification","scId":"non-text-content","prompt":"Which principle includes 1.1.1 Non-text Content?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-non-text-content","type":"typed","skill":"recall","scId":"non-text-content","prompt":"Type the key requirement for 1.1.1 Non-text Content.","answer":"All non-text content that is presented to the user has a text alternative that serves the equivalent purpose, except for the situations listed below. Controls, Input If non-text content is a control or accepts user input, then it has a name that describes its purpose. (Refer to Success Criterion 4.1.2 for additional requirements for controls and content that accepts user input.) Time-Based Media If non-text content is time-based media, then text alternatives at least provide descriptive identification of the non-text content. (Refer to Guideline 1.2 for additional requirements for media.) Test If non-text content is a test or exercise that would be invalid if presented in text , then text alternatives at least provide descriptive identification of the non-text content. Sensory If non-text content is primarily intended to create a specific sensory experience , then text alternatives at least provide descriptive identification of the non-text content. CAPTCHA If the purpose of non-text content is to confirm that content is being accessed by a person rather than a computer, then text alternatives that identify and describe the purpose of the non-text content are provided, and alternative forms of CAPTCHA using output modes for different types of sensory perception are provided to accommodate different disabilities. Decoration, Formatting, Invisible If non-text content is pure decoration , is used only for visual formatting, or is not presented to users, then it is implemented in a way that it can be ignored by assistive technology ."},{"id":"sc-title-audio-only-and-video-only-prerecorded","type":"mcq","skill":"recognition","scId":"audio-only-and-video-only-prerecorded","prompt":"Which success criterion matches: Audio-only and Video-only (Prerecorded)?","answer":"1.2.1","choices":["1.2.1","1.1.1","1.2.2","1.2.3"]},{"id":"sc-level-audio-only-and-video-only-prerecorded","type":"mcq","skill":"classification","scId":"audio-only-and-video-only-prerecorded","prompt":"What conformance level is 1.2.1 Audio-only and Video-only (Prerecorded)?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-audio-only-and-video-only-prerecorded","type":"mcq","skill":"classification","scId":"audio-only-and-video-only-prerecorded","prompt":"Which principle includes 1.2.1 Audio-only and Video-only (Prerecorded)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-audio-only-and-video-only-prerecorded","type":"typed","skill":"recall","scId":"audio-only-and-video-only-prerecorded","prompt":"Type the key requirement for 1.2.1 Audio-only and Video-only (Prerecorded).","answer":"For prerecorded audio-only and prerecorded video-only media, the following are true, except when the audio or video is a media alternative for text and is clearly labeled as such: Prerecorded Audio-only An alternative for time-based media is provided that presents equivalent information for prerecorded audio-only content. Prerecorded Video-only Either an alternative for time-based media or an audio track is provided that presents equivalent information for prerecorded video-only content."},{"id":"sc-title-captions-prerecorded","type":"mcq","skill":"recognition","scId":"captions-prerecorded","prompt":"Which success criterion matches: Captions (Prerecorded)?","answer":"1.2.2","choices":["1.2.2","1.1.1","1.2.1","1.2.3"]},{"id":"sc-level-captions-prerecorded","type":"mcq","skill":"classification","scId":"captions-prerecorded","prompt":"What conformance level is 1.2.2 Captions (Prerecorded)?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-captions-prerecorded","type":"mcq","skill":"classification","scId":"captions-prerecorded","prompt":"Which principle includes 1.2.2 Captions (Prerecorded)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-captions-prerecorded","type":"typed","skill":"recall","scId":"captions-prerecorded","prompt":"Type the key requirement for 1.2.2 Captions (Prerecorded).","answer":"Captions are provided for all prerecorded audio content in synchronized media , except when the media is a media alternative for text and is clearly labeled as such."},{"id":"sc-title-audio-description-or-media-alternative-prerecorded","type":"mcq","skill":"recognition","scId":"audio-description-or-media-alternative-prerecorded","prompt":"Which success criterion matches: Audio Description or Media Alternative (Prerecorded)?","answer":"1.2.3","choices":["1.2.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-audio-description-or-media-alternative-prerecorded","type":"mcq","skill":"classification","scId":"audio-description-or-media-alternative-prerecorded","prompt":"What conformance level is 1.2.3 Audio Description or Media Alternative (Prerecorded)?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-audio-description-or-media-alternative-prerecorded","type":"mcq","skill":"classification","scId":"audio-description-or-media-alternative-prerecorded","prompt":"Which principle includes 1.2.3 Audio Description or Media Alternative (Prerecorded)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-audio-description-or-media-alternative-prerecorded","type":"typed","skill":"recall","scId":"audio-description-or-media-alternative-prerecorded","prompt":"Type the key requirement for 1.2.3 Audio Description or Media Alternative (Prerecorded).","answer":"An alternative for time-based media or audio description of the prerecorded video content is provided for synchronized media , except when the media is a media alternative for text and is clearly labeled as such."},{"id":"sc-title-captions-live","type":"mcq","skill":"recognition","scId":"captions-live","prompt":"Which success criterion matches: Captions (Live)?","answer":"1.2.4","choices":["1.2.4","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-captions-live","type":"mcq","skill":"classification","scId":"captions-live","prompt":"What conformance level is 1.2.4 Captions (Live)?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-captions-live","type":"mcq","skill":"classification","scId":"captions-live","prompt":"Which principle includes 1.2.4 Captions (Live)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-captions-live","type":"typed","skill":"recall","scId":"captions-live","prompt":"Type the key requirement for 1.2.4 Captions (Live).","answer":"Captions are provided for all live audio content in synchronized media ."},{"id":"sc-title-audio-description-prerecorded","type":"mcq","skill":"recognition","scId":"audio-description-prerecorded","prompt":"Which success criterion matches: Audio Description (Prerecorded)?","answer":"1.2.5","choices":["1.2.5","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-audio-description-prerecorded","type":"mcq","skill":"classification","scId":"audio-description-prerecorded","prompt":"What conformance level is 1.2.5 Audio Description (Prerecorded)?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-audio-description-prerecorded","type":"mcq","skill":"classification","scId":"audio-description-prerecorded","prompt":"Which principle includes 1.2.5 Audio Description (Prerecorded)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-audio-description-prerecorded","type":"typed","skill":"recall","scId":"audio-description-prerecorded","prompt":"Type the key requirement for 1.2.5 Audio Description (Prerecorded).","answer":"Audio description is provided for all prerecorded video content in synchronized media ."},{"id":"sc-title-sign-language-prerecorded","type":"mcq","skill":"recognition","scId":"sign-language-prerecorded","prompt":"Which success criterion matches: Sign Language (Prerecorded)?","answer":"1.2.6","choices":["1.2.6","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-sign-language-prerecorded","type":"mcq","skill":"classification","scId":"sign-language-prerecorded","prompt":"What conformance level is 1.2.6 Sign Language (Prerecorded)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-sign-language-prerecorded","type":"mcq","skill":"classification","scId":"sign-language-prerecorded","prompt":"Which principle includes 1.2.6 Sign Language (Prerecorded)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-sign-language-prerecorded","type":"typed","skill":"recall","scId":"sign-language-prerecorded","prompt":"Type the key requirement for 1.2.6 Sign Language (Prerecorded).","answer":"Sign language interpretation is provided for all prerecorded audio content in synchronized media ."},{"id":"sc-title-extended-audio-description-prerecorded","type":"mcq","skill":"recognition","scId":"extended-audio-description-prerecorded","prompt":"Which success criterion matches: Extended Audio Description (Prerecorded)?","answer":"1.2.7","choices":["1.2.7","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-extended-audio-description-prerecorded","type":"mcq","skill":"classification","scId":"extended-audio-description-prerecorded","prompt":"What conformance level is 1.2.7 Extended Audio Description (Prerecorded)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-extended-audio-description-prerecorded","type":"mcq","skill":"classification","scId":"extended-audio-description-prerecorded","prompt":"Which principle includes 1.2.7 Extended Audio Description (Prerecorded)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-extended-audio-description-prerecorded","type":"typed","skill":"recall","scId":"extended-audio-description-prerecorded","prompt":"Type the key requirement for 1.2.7 Extended Audio Description (Prerecorded).","answer":"Where pauses in foreground audio are insufficient to allow audio descriptions to convey the sense of the video, extended audio description is provided for all prerecorded video content in synchronized media ."},{"id":"sc-title-media-alternative-prerecorded","type":"mcq","skill":"recognition","scId":"media-alternative-prerecorded","prompt":"Which success criterion matches: Media Alternative (Prerecorded)?","answer":"1.2.8","choices":["1.2.8","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-media-alternative-prerecorded","type":"mcq","skill":"classification","scId":"media-alternative-prerecorded","prompt":"What conformance level is 1.2.8 Media Alternative (Prerecorded)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-media-alternative-prerecorded","type":"mcq","skill":"classification","scId":"media-alternative-prerecorded","prompt":"Which principle includes 1.2.8 Media Alternative (Prerecorded)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-media-alternative-prerecorded","type":"typed","skill":"recall","scId":"media-alternative-prerecorded","prompt":"Type the key requirement for 1.2.8 Media Alternative (Prerecorded).","answer":"An alternative for time-based media is provided for all prerecorded synchronized media and for all prerecorded video-only media."},{"id":"sc-title-audio-only-live","type":"mcq","skill":"recognition","scId":"audio-only-live","prompt":"Which success criterion matches: Audio-only (Live)?","answer":"1.2.9","choices":["1.2.9","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-audio-only-live","type":"mcq","skill":"classification","scId":"audio-only-live","prompt":"What conformance level is 1.2.9 Audio-only (Live)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-audio-only-live","type":"mcq","skill":"classification","scId":"audio-only-live","prompt":"Which principle includes 1.2.9 Audio-only (Live)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-audio-only-live","type":"typed","skill":"recall","scId":"audio-only-live","prompt":"Type the key requirement for 1.2.9 Audio-only (Live).","answer":"An alternative for time-based media that presents equivalent information for live audio-only content is provided."},{"id":"sc-title-info-and-relationships","type":"mcq","skill":"recognition","scId":"info-and-relationships","prompt":"Which success criterion matches: Info and Relationships?","answer":"1.3.1","choices":["1.3.1","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-info-and-relationships","type":"mcq","skill":"classification","scId":"info-and-relationships","prompt":"What conformance level is 1.3.1 Info and Relationships?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-info-and-relationships","type":"mcq","skill":"classification","scId":"info-and-relationships","prompt":"Which principle includes 1.3.1 Info and Relationships?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-info-and-relationships","type":"typed","skill":"recall","scId":"info-and-relationships","prompt":"Type the key requirement for 1.3.1 Info and Relationships.","answer":"Information, structure , and relationships conveyed through presentation can be programmatically determined or are available in text."},{"id":"sc-title-meaningful-sequence","type":"mcq","skill":"recognition","scId":"meaningful-sequence","prompt":"Which success criterion matches: Meaningful Sequence?","answer":"1.3.2","choices":["1.3.2","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-meaningful-sequence","type":"mcq","skill":"classification","scId":"meaningful-sequence","prompt":"What conformance level is 1.3.2 Meaningful Sequence?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-meaningful-sequence","type":"mcq","skill":"classification","scId":"meaningful-sequence","prompt":"Which principle includes 1.3.2 Meaningful Sequence?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-meaningful-sequence","type":"typed","skill":"recall","scId":"meaningful-sequence","prompt":"Type the key requirement for 1.3.2 Meaningful Sequence.","answer":"When the sequence in which content is presented affects its meaning, a correct reading sequence can be programmatically determined ."},{"id":"sc-title-sensory-characteristics","type":"mcq","skill":"recognition","scId":"sensory-characteristics","prompt":"Which success criterion matches: Sensory Characteristics?","answer":"1.3.3","choices":["1.3.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-sensory-characteristics","type":"mcq","skill":"classification","scId":"sensory-characteristics","prompt":"What conformance level is 1.3.3 Sensory Characteristics?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-sensory-characteristics","type":"mcq","skill":"classification","scId":"sensory-characteristics","prompt":"Which principle includes 1.3.3 Sensory Characteristics?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-sensory-characteristics","type":"typed","skill":"recall","scId":"sensory-characteristics","prompt":"Type the key requirement for 1.3.3 Sensory Characteristics.","answer":"Instructions provided for understanding and operating content do not rely solely on sensory characteristics of components such as shape, color, size, visual location, orientation, or sound. Note For requirements related to color, refer to Guideline 1.4 ."},{"id":"sc-title-orientation","type":"mcq","skill":"recognition","scId":"orientation","prompt":"Which success criterion matches: Orientation?","answer":"1.3.4","choices":["1.3.4","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-orientation","type":"mcq","skill":"classification","scId":"orientation","prompt":"What conformance level is 1.3.4 Orientation?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-orientation","type":"mcq","skill":"classification","scId":"orientation","prompt":"Which principle includes 1.3.4 Orientation?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-orientation","type":"typed","skill":"recall","scId":"orientation","prompt":"Type the key requirement for 1.3.4 Orientation.","answer":"Content does not restrict its view and operation to a single display orientation, such as portrait or landscape, unless a specific display orientation is essential . Note Examples where a particular display orientation may be essential are a bank check, a piano application, slides for a projector or television, or virtual reality content where content is not necessarily restricted to landscape or portrait display orientation."},{"id":"sc-title-identify-input-purpose","type":"mcq","skill":"recognition","scId":"identify-input-purpose","prompt":"Which success criterion matches: Identify Input Purpose?","answer":"1.3.5","choices":["1.3.5","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-identify-input-purpose","type":"mcq","skill":"classification","scId":"identify-input-purpose","prompt":"What conformance level is 1.3.5 Identify Input Purpose?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-identify-input-purpose","type":"mcq","skill":"classification","scId":"identify-input-purpose","prompt":"Which principle includes 1.3.5 Identify Input Purpose?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-identify-input-purpose","type":"typed","skill":"recall","scId":"identify-input-purpose","prompt":"Type the key requirement for 1.3.5 Identify Input Purpose.","answer":"The purpose of each input field collecting information about the user can be programmatically determined when: The input field serves a purpose identified in the Input Purposes for user interface components section ; and The content is implemented using technologies with support for identifying the expected meaning for form input data."},{"id":"sc-title-identify-purpose","type":"mcq","skill":"recognition","scId":"identify-purpose","prompt":"Which success criterion matches: Identify Purpose?","answer":"1.3.6","choices":["1.3.6","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-identify-purpose","type":"mcq","skill":"classification","scId":"identify-purpose","prompt":"What conformance level is 1.3.6 Identify Purpose?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-identify-purpose","type":"mcq","skill":"classification","scId":"identify-purpose","prompt":"Which principle includes 1.3.6 Identify Purpose?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-identify-purpose","type":"typed","skill":"recall","scId":"identify-purpose","prompt":"Type the key requirement for 1.3.6 Identify Purpose.","answer":"In content implemented using markup languages, the purpose of user interface components , icons, and regions can be programmatically determined ."},{"id":"sc-title-use-of-color","type":"mcq","skill":"recognition","scId":"use-of-color","prompt":"Which success criterion matches: Use of Color?","answer":"1.4.1","choices":["1.4.1","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-use-of-color","type":"mcq","skill":"classification","scId":"use-of-color","prompt":"What conformance level is 1.4.1 Use of Color?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-use-of-color","type":"mcq","skill":"classification","scId":"use-of-color","prompt":"Which principle includes 1.4.1 Use of Color?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-use-of-color","type":"typed","skill":"recall","scId":"use-of-color","prompt":"Type the key requirement for 1.4.1 Use of Color.","answer":"Color is not used as the only visual means of conveying information, indicating an action, prompting a response, or distinguishing a visual element. Note This success criterion addresses color perception specifically. Other forms of perception are covered in Guideline 1.3 including programmatic access to color and other visual presentation coding."},{"id":"sc-title-audio-control","type":"mcq","skill":"recognition","scId":"audio-control","prompt":"Which success criterion matches: Audio Control?","answer":"1.4.2","choices":["1.4.2","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-audio-control","type":"mcq","skill":"classification","scId":"audio-control","prompt":"What conformance level is 1.4.2 Audio Control?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-audio-control","type":"mcq","skill":"classification","scId":"audio-control","prompt":"Which principle includes 1.4.2 Audio Control?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-audio-control","type":"typed","skill":"recall","scId":"audio-control","prompt":"Type the key requirement for 1.4.2 Audio Control.","answer":"If any audio on a web page plays automatically for more than 3 seconds, either a mechanism is available to pause or stop the audio, or a mechanism is available to control audio volume independently from the overall system volume level. Note Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether or not it is used to meet other success criteria) must meet this success criterion. See Conformance Requirement 5: Non-Interference ."},{"id":"sc-title-contrast-minimum","type":"mcq","skill":"recognition","scId":"contrast-minimum","prompt":"Which success criterion matches: Contrast (Minimum)?","answer":"1.4.3","choices":["1.4.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-contrast-minimum","type":"mcq","skill":"classification","scId":"contrast-minimum","prompt":"What conformance level is 1.4.3 Contrast (Minimum)?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-contrast-minimum","type":"mcq","skill":"classification","scId":"contrast-minimum","prompt":"Which principle includes 1.4.3 Contrast (Minimum)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-contrast-minimum","type":"typed","skill":"recall","scId":"contrast-minimum","prompt":"Type the key requirement for 1.4.3 Contrast (Minimum).","answer":"The visual presentation of text and images of text has a contrast ratio of at least 4.5:1, except for the following: Large Text Large-scale text and images of large-scale text have a contrast ratio of at least 3:1; Incidental Text or images of text that are part of an inactive user interface component , that are pure decoration , that are not visible to anyone, or that are part of a picture that contains significant other visual content, have no contrast requirement. Logotypes Text that is part of a logo or brand name has no contrast requirement."},{"id":"sc-title-resize-text","type":"mcq","skill":"recognition","scId":"resize-text","prompt":"Which success criterion matches: Resize Text?","answer":"1.4.4","choices":["1.4.4","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-resize-text","type":"mcq","skill":"classification","scId":"resize-text","prompt":"What conformance level is 1.4.4 Resize Text?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-resize-text","type":"mcq","skill":"classification","scId":"resize-text","prompt":"Which principle includes 1.4.4 Resize Text?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-resize-text","type":"typed","skill":"recall","scId":"resize-text","prompt":"Type the key requirement for 1.4.4 Resize Text.","answer":"Except for captions and images of text , text can be resized without assistive technology up to 200 percent without loss of content or functionality."},{"id":"sc-title-images-of-text","type":"mcq","skill":"recognition","scId":"images-of-text","prompt":"Which success criterion matches: Images of Text?","answer":"1.4.5","choices":["1.4.5","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-images-of-text","type":"mcq","skill":"classification","scId":"images-of-text","prompt":"What conformance level is 1.4.5 Images of Text?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-images-of-text","type":"mcq","skill":"classification","scId":"images-of-text","prompt":"Which principle includes 1.4.5 Images of Text?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-images-of-text","type":"typed","skill":"recall","scId":"images-of-text","prompt":"Type the key requirement for 1.4.5 Images of Text.","answer":"If the technologies being used can achieve the visual presentation, text is used to convey information rather than images of text except for the following: Customizable The image of text can be visually customized to the user's requirements; Essential A particular presentation of text is essential to the information being conveyed. Note Logotypes (text that is part of a logo or brand name) are considered essential."},{"id":"sc-title-contrast-enhanced","type":"mcq","skill":"recognition","scId":"contrast-enhanced","prompt":"Which success criterion matches: Contrast (Enhanced)?","answer":"1.4.6","choices":["1.4.6","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-contrast-enhanced","type":"mcq","skill":"classification","scId":"contrast-enhanced","prompt":"What conformance level is 1.4.6 Contrast (Enhanced)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-contrast-enhanced","type":"mcq","skill":"classification","scId":"contrast-enhanced","prompt":"Which principle includes 1.4.6 Contrast (Enhanced)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-contrast-enhanced","type":"typed","skill":"recall","scId":"contrast-enhanced","prompt":"Type the key requirement for 1.4.6 Contrast (Enhanced).","answer":"The visual presentation of text and images of text has a contrast ratio of at least 7:1, except for the following: Large Text Large-scale text and images of large-scale text have a contrast ratio of at least 4.5:1; Incidental Text or images of text that are part of an inactive user interface component , that are pure decoration , that are not visible to anyone, or that are part of a picture that contains significant other visual content, have no contrast requirement. Logotypes Text that is part of a logo or brand name has no contrast requirement."},{"id":"sc-title-low-or-no-background-audio","type":"mcq","skill":"recognition","scId":"low-or-no-background-audio","prompt":"Which success criterion matches: Low or No Background Audio?","answer":"1.4.7","choices":["1.4.7","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-low-or-no-background-audio","type":"mcq","skill":"classification","scId":"low-or-no-background-audio","prompt":"What conformance level is 1.4.7 Low or No Background Audio?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-low-or-no-background-audio","type":"mcq","skill":"classification","scId":"low-or-no-background-audio","prompt":"Which principle includes 1.4.7 Low or No Background Audio?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-low-or-no-background-audio","type":"typed","skill":"recall","scId":"low-or-no-background-audio","prompt":"Type the key requirement for 1.4.7 Low or No Background Audio.","answer":"For prerecorded audio-only content that (1) contains primarily speech in the foreground, (2) is not an audio CAPTCHA or audio logo, and (3) is not vocalization intended to be primarily musical expression such as singing or rapping, at least one of the following is true: No Background The audio does not contain background sounds. Turn Off The background sounds can be turned off. 20 dB The background sounds are at least 20 decibels lower than the foreground speech content, with the exception of occasional sounds that last for only one or two seconds. Note Per the definition of \\"decibel,\\" background sound that meets this requirement will be approximately four times quieter than the foreground speech content."},{"id":"sc-title-visual-presentation","type":"mcq","skill":"recognition","scId":"visual-presentation","prompt":"Which success criterion matches: Visual Presentation?","answer":"1.4.8","choices":["1.4.8","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-visual-presentation","type":"mcq","skill":"classification","scId":"visual-presentation","prompt":"What conformance level is 1.4.8 Visual Presentation?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-visual-presentation","type":"mcq","skill":"classification","scId":"visual-presentation","prompt":"Which principle includes 1.4.8 Visual Presentation?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-visual-presentation","type":"typed","skill":"recall","scId":"visual-presentation","prompt":"Type the key requirement for 1.4.8 Visual Presentation.","answer":"For the visual presentation of blocks of text , a mechanism is available to achieve the following: Foreground and background colors can be selected by the user. Width is no more than 80 characters or glyphs (40 if CJK). Text is not justified (aligned to both the left and the right margins). Line spacing (leading) is at least space-and-a-half within paragraphs, and paragraph spacing is at least 1.5 times larger than the line spacing. Text can be resized without assistive technology up to 200 percent in a way that does not require the user to scroll horizontally to read a line of text on a full-screen window . Note 1 Content is not required to use these values. The requirement is that a mechanism is available for users to change these presentation aspects. The mechanism can be provided by the browser or other user agent. Content is not required to provide the mechanism. Note 2 Writing systems for some languages use different presentation aspects to improve readability and legibility. If a presentation aspect in this success criterion is not used in a writing system, content in that writing system does not need to use that presentation setting and can conform without it. Authors are encouraged to follow guidance for improving readability and legibility of text in their writing system."},{"id":"sc-title-images-of-text-no-exception","type":"mcq","skill":"recognition","scId":"images-of-text-no-exception","prompt":"Which success criterion matches: Images of Text (No Exception)?","answer":"1.4.9","choices":["1.4.9","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-images-of-text-no-exception","type":"mcq","skill":"classification","scId":"images-of-text-no-exception","prompt":"What conformance level is 1.4.9 Images of Text (No Exception)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-images-of-text-no-exception","type":"mcq","skill":"classification","scId":"images-of-text-no-exception","prompt":"Which principle includes 1.4.9 Images of Text (No Exception)?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-images-of-text-no-exception","type":"typed","skill":"recall","scId":"images-of-text-no-exception","prompt":"Type the key requirement for 1.4.9 Images of Text (No Exception).","answer":"Images of text are only used for pure decoration or where a particular presentation of text is essential to the information being conveyed. Note Logotypes (text that is part of a logo or brand name) are considered essential."},{"id":"sc-title-reflow","type":"mcq","skill":"recognition","scId":"reflow","prompt":"Which success criterion matches: Reflow?","answer":"1.4.10","choices":["1.4.10","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-reflow","type":"mcq","skill":"classification","scId":"reflow","prompt":"What conformance level is 1.4.10 Reflow?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-reflow","type":"mcq","skill":"classification","scId":"reflow","prompt":"Which principle includes 1.4.10 Reflow?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-reflow","type":"typed","skill":"recall","scId":"reflow","prompt":"Type the key requirement for 1.4.10 Reflow.","answer":"Content can be presented without loss of information or functionality, and without requiring scrolling in two dimensions for: Vertical scrolling content at a width equivalent to 320 CSS pixels ; Horizontal scrolling content at a height equivalent to 256 CSS pixels . Except for parts of the content which require two-dimensional layout for usage or meaning. Note 1 320 CSS pixels is equivalent to a starting viewport width of 1280 CSS pixels wide at 400% zoom. For web content which is designed to scroll horizontally (e.g., with vertical text), 256 CSS pixels is equivalent to a starting viewport height of 1024 CSS pixels at 400% zoom. Note 2 Examples of content which requires two-dimensional layout are images required for understanding (such as maps and diagrams), video, games, presentations, data tables (not individual cells), and interfaces where it is necessary to keep toolbars in view while manipulating content. It is acceptable to provide two-dimensional scrolling for such parts of the content."},{"id":"sc-title-non-text-contrast","type":"mcq","skill":"recognition","scId":"non-text-contrast","prompt":"Which success criterion matches: Non-text Contrast?","answer":"1.4.11","choices":["1.4.11","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-non-text-contrast","type":"mcq","skill":"classification","scId":"non-text-contrast","prompt":"What conformance level is 1.4.11 Non-text Contrast?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-non-text-contrast","type":"mcq","skill":"classification","scId":"non-text-contrast","prompt":"Which principle includes 1.4.11 Non-text Contrast?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-non-text-contrast","type":"typed","skill":"recall","scId":"non-text-contrast","prompt":"Type the key requirement for 1.4.11 Non-text Contrast.","answer":"The visual presentation of the following have a contrast ratio of at least 3:1 against adjacent color(s): User Interface Components Visual information required to identify user interface components and states , except for inactive components or where the appearance of the component is determined by the user agent and not modified by the author; Graphical Objects Parts of graphics required to understand the content, except when a particular presentation of graphics is essential to the information being conveyed."},{"id":"sc-title-text-spacing","type":"mcq","skill":"recognition","scId":"text-spacing","prompt":"Which success criterion matches: Text Spacing?","answer":"1.4.12","choices":["1.4.12","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-text-spacing","type":"mcq","skill":"classification","scId":"text-spacing","prompt":"What conformance level is 1.4.12 Text Spacing?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-text-spacing","type":"mcq","skill":"classification","scId":"text-spacing","prompt":"Which principle includes 1.4.12 Text Spacing?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-text-spacing","type":"typed","skill":"recall","scId":"text-spacing","prompt":"Type the key requirement for 1.4.12 Text Spacing.","answer":"In content implemented using markup languages that support the following text style properties , no loss of content or functionality occurs by setting all of the following and by changing no other style property: Line height (line spacing) to at least 1.5 times the font size; Spacing following paragraphs to at least 2 times the font size; Letter spacing (tracking) to at least 0.12 times the font size; Word spacing to at least 0.16 times the font size. Exception: Human languages and scripts that do not make use of one or more of these text style properties in written text can conform using only the properties that exist for that combination of language and script. Note 1 Content is not required to use these text spacing values. The requirement is to ensure that when a user overrides the authored text spacing, content or functionality is not lost. Note 2 Writing systems for some languages use different text spacing settings, such as paragraph start indent. Authors are encouraged to follow locally available guidance for improving readability and legibility of text in their writing system."},{"id":"sc-title-content-on-hover-or-focus","type":"mcq","skill":"recognition","scId":"content-on-hover-or-focus","prompt":"Which success criterion matches: Content on Hover or Focus?","answer":"1.4.13","choices":["1.4.13","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-content-on-hover-or-focus","type":"mcq","skill":"classification","scId":"content-on-hover-or-focus","prompt":"What conformance level is 1.4.13 Content on Hover or Focus?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-content-on-hover-or-focus","type":"mcq","skill":"classification","scId":"content-on-hover-or-focus","prompt":"Which principle includes 1.4.13 Content on Hover or Focus?","answer":"Perceivable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-content-on-hover-or-focus","type":"typed","skill":"recall","scId":"content-on-hover-or-focus","prompt":"Type the key requirement for 1.4.13 Content on Hover or Focus.","answer":"Where receiving and then removing pointer hover or keyboard focus triggers additional content to become visible and then hidden, the following are true: Dismissible A mechanism is available to dismiss the additional content without moving pointer hover or keyboard focus, unless the additional content communicates an input error or does not obscure or replace other content; Hoverable If pointer hover can trigger the additional content, then the pointer can be moved over the additional content without the additional content disappearing; Persistent The additional content remains visible until the hover or focus trigger is removed, the user dismisses it, or its information is no longer valid. Exception: The visual presentation of the additional content is controlled by the user agent and is not modified by the author. Note 1 Examples of additional content controlled by the user agent include browser tooltips created through use of the HTML title attribute [ HTML ]. Note 2 Custom tooltips, sub-menus, and other nonmodal popups that display on hover and focus are examples of additional content covered by this criterion. Note 3 This criterion applies to content that appears in addition to the triggering component itself. Since hidden components that are made visible on keyboard focus (such as links used to skip to another part of a page) do not present additional content they are not covered by this criterion."},{"id":"sc-title-keyboard","type":"mcq","skill":"recognition","scId":"keyboard","prompt":"Which success criterion matches: Keyboard?","answer":"2.1.1","choices":["2.1.1","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-keyboard","type":"mcq","skill":"classification","scId":"keyboard","prompt":"What conformance level is 2.1.1 Keyboard?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-keyboard","type":"mcq","skill":"classification","scId":"keyboard","prompt":"Which principle includes 2.1.1 Keyboard?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-keyboard","type":"typed","skill":"recall","scId":"keyboard","prompt":"Type the key requirement for 2.1.1 Keyboard.","answer":"All functionality of the content is operable through a keyboard interface without requiring specific timings for individual keystrokes, except where the underlying function requires input that depends on the path of the user's movement and not just the endpoints. Note 1 This exception relates to the underlying function, not the input technique. For example, if using handwriting to enter text, the input technique (handwriting) requires path-dependent input but the underlying function (text input) does not. Note 2 This does not forbid and should not discourage providing mouse input or other input methods in addition to keyboard operation."},{"id":"sc-title-no-keyboard-trap","type":"mcq","skill":"recognition","scId":"no-keyboard-trap","prompt":"Which success criterion matches: No Keyboard Trap?","answer":"2.1.2","choices":["2.1.2","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-no-keyboard-trap","type":"mcq","skill":"classification","scId":"no-keyboard-trap","prompt":"What conformance level is 2.1.2 No Keyboard Trap?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-no-keyboard-trap","type":"mcq","skill":"classification","scId":"no-keyboard-trap","prompt":"Which principle includes 2.1.2 No Keyboard Trap?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-no-keyboard-trap","type":"typed","skill":"recall","scId":"no-keyboard-trap","prompt":"Type the key requirement for 2.1.2 No Keyboard Trap.","answer":"If keyboard focus can be moved to a component of the page using a keyboard interface , then focus can be moved away from that component using only a keyboard interface, and, if it requires more than unmodified arrow or tab keys or other standard exit methods, the user is advised of the method for moving focus away. Note Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether it is used to meet other success criteria or not) must meet this success criterion. See Conformance Requirement 5: Non-Interference ."},{"id":"sc-title-keyboard-no-exception","type":"mcq","skill":"recognition","scId":"keyboard-no-exception","prompt":"Which success criterion matches: Keyboard (No Exception)?","answer":"2.1.3","choices":["2.1.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-keyboard-no-exception","type":"mcq","skill":"classification","scId":"keyboard-no-exception","prompt":"What conformance level is 2.1.3 Keyboard (No Exception)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-keyboard-no-exception","type":"mcq","skill":"classification","scId":"keyboard-no-exception","prompt":"Which principle includes 2.1.3 Keyboard (No Exception)?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-keyboard-no-exception","type":"typed","skill":"recall","scId":"keyboard-no-exception","prompt":"Type the key requirement for 2.1.3 Keyboard (No Exception).","answer":"All functionality of the content is operable through a keyboard interface without requiring specific timings for individual keystrokes."},{"id":"sc-title-character-key-shortcuts","type":"mcq","skill":"recognition","scId":"character-key-shortcuts","prompt":"Which success criterion matches: Character Key Shortcuts?","answer":"2.1.4","choices":["2.1.4","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-character-key-shortcuts","type":"mcq","skill":"classification","scId":"character-key-shortcuts","prompt":"What conformance level is 2.1.4 Character Key Shortcuts?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-character-key-shortcuts","type":"mcq","skill":"classification","scId":"character-key-shortcuts","prompt":"Which principle includes 2.1.4 Character Key Shortcuts?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-character-key-shortcuts","type":"typed","skill":"recall","scId":"character-key-shortcuts","prompt":"Type the key requirement for 2.1.4 Character Key Shortcuts.","answer":"If a keyboard shortcut is implemented in content using only letter (including upper- and lower-case letters), punctuation, number, or symbol characters, then at least one of the following is true: Turn off A mechanism is available to turn the shortcut off; Remap A mechanism is available to remap the shortcut to include one or more non-printable keyboard keys (e.g., Ctrl, Alt); Active only on focus The keyboard shortcut for a user interface component is only active when that component has focus."},{"id":"sc-title-timing-adjustable","type":"mcq","skill":"recognition","scId":"timing-adjustable","prompt":"Which success criterion matches: Timing Adjustable?","answer":"2.2.1","choices":["2.2.1","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-timing-adjustable","type":"mcq","skill":"classification","scId":"timing-adjustable","prompt":"What conformance level is 2.2.1 Timing Adjustable?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-timing-adjustable","type":"mcq","skill":"classification","scId":"timing-adjustable","prompt":"Which principle includes 2.2.1 Timing Adjustable?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-timing-adjustable","type":"typed","skill":"recall","scId":"timing-adjustable","prompt":"Type the key requirement for 2.2.1 Timing Adjustable.","answer":"For each time limit that is set by the content, at least one of the following is true: Turn off The user is allowed to turn off the time limit before encountering it; or Adjust The user is allowed to adjust the time limit before encountering it over a wide range that is at least ten times the length of the default setting; or Extend The user is warned before time expires and given at least 20 seconds to extend the time limit with a simple action (for example, \\"press the space bar\\"), and the user is allowed to extend the time limit at least ten times; or Real-time Exception The time limit is a required part of a real-time event (for example, an auction), and no alternative to the time limit is possible; or Essential Exception The time limit is essential and extending it would invalidate the activity; or 20 Hour Exception The time limit is longer than 20 hours. Note This success criterion helps ensure that users can complete tasks without unexpected changes in content or context that are a result of a time limit. This success criterion should be considered in conjunction with Success Criterion 3.2.1 , which puts limits on changes of content or context as a result of user action."},{"id":"sc-title-pause-stop-hide","type":"mcq","skill":"recognition","scId":"pause-stop-hide","prompt":"Which success criterion matches: Pause, Stop, Hide?","answer":"2.2.2","choices":["2.2.2","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-pause-stop-hide","type":"mcq","skill":"classification","scId":"pause-stop-hide","prompt":"What conformance level is 2.2.2 Pause, Stop, Hide?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-pause-stop-hide","type":"mcq","skill":"classification","scId":"pause-stop-hide","prompt":"Which principle includes 2.2.2 Pause, Stop, Hide?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-pause-stop-hide","type":"typed","skill":"recall","scId":"pause-stop-hide","prompt":"Type the key requirement for 2.2.2 Pause, Stop, Hide.","answer":"For moving, blinking , scrolling, or auto-updating information, all of the following are true: Moving, blinking, scrolling For any moving, blinking or scrolling information that (1) starts automatically, (2) lasts more than five seconds, and (3) is presented in parallel with other content, there is a mechanism for the user to pause , stop, or hide it unless the movement, blinking, or scrolling is part of an activity where it is essential ; and Auto-updating For any auto-updating information that (1) starts automatically and (2) is presented in parallel with other content, there is a mechanism for the user to pause, stop, or hide it or to control the frequency of the update unless the auto-updating is part of an activity where it is essential. Note 1 For requirements related to flickering or flashing content, refer to Guideline 2.3 . Note 2 Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether it is used to meet other success criteria or not) must meet this success criterion. See Conformance Requirement 5: Non-Interference . Note 3 Content that is updated periodically by software or that is streamed to the user agent is not required to preserve or present information that is generated or received between the initiation of the pause and resuming presentation, as this may not be technically possible, and in many situations could be misleading to do so. Note 4 An animation that occurs as part of a preload phase or similar situation can be considered essential if interaction cannot occur during that phase for all users and if not indicating progress could confuse users or cause them to think that content was frozen or broken."},{"id":"sc-title-no-timing","type":"mcq","skill":"recognition","scId":"no-timing","prompt":"Which success criterion matches: No Timing?","answer":"2.2.3","choices":["2.2.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-no-timing","type":"mcq","skill":"classification","scId":"no-timing","prompt":"What conformance level is 2.2.3 No Timing?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-no-timing","type":"mcq","skill":"classification","scId":"no-timing","prompt":"Which principle includes 2.2.3 No Timing?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-no-timing","type":"typed","skill":"recall","scId":"no-timing","prompt":"Type the key requirement for 2.2.3 No Timing.","answer":"Timing is not an essential part of the event or activity presented by the content, except for non-interactive synchronized media and real-time events ."},{"id":"sc-title-interruptions","type":"mcq","skill":"recognition","scId":"interruptions","prompt":"Which success criterion matches: Interruptions?","answer":"2.2.4","choices":["2.2.4","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-interruptions","type":"mcq","skill":"classification","scId":"interruptions","prompt":"What conformance level is 2.2.4 Interruptions?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-interruptions","type":"mcq","skill":"classification","scId":"interruptions","prompt":"Which principle includes 2.2.4 Interruptions?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-interruptions","type":"typed","skill":"recall","scId":"interruptions","prompt":"Type the key requirement for 2.2.4 Interruptions.","answer":"Interruptions can be postponed or suppressed by the user, except interruptions involving an emergency ."},{"id":"sc-title-re-authenticating","type":"mcq","skill":"recognition","scId":"re-authenticating","prompt":"Which success criterion matches: Re-authenticating?","answer":"2.2.5","choices":["2.2.5","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-re-authenticating","type":"mcq","skill":"classification","scId":"re-authenticating","prompt":"What conformance level is 2.2.5 Re-authenticating?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-re-authenticating","type":"mcq","skill":"classification","scId":"re-authenticating","prompt":"Which principle includes 2.2.5 Re-authenticating?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-re-authenticating","type":"typed","skill":"recall","scId":"re-authenticating","prompt":"Type the key requirement for 2.2.5 Re-authenticating.","answer":"When an authenticated session expires, the user can continue the activity without loss of data after re-authenticating."},{"id":"sc-title-timeouts","type":"mcq","skill":"recognition","scId":"timeouts","prompt":"Which success criterion matches: Timeouts?","answer":"2.2.6","choices":["2.2.6","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-timeouts","type":"mcq","skill":"classification","scId":"timeouts","prompt":"What conformance level is 2.2.6 Timeouts?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-timeouts","type":"mcq","skill":"classification","scId":"timeouts","prompt":"Which principle includes 2.2.6 Timeouts?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-timeouts","type":"typed","skill":"recall","scId":"timeouts","prompt":"Type the key requirement for 2.2.6 Timeouts.","answer":"Users are warned of the duration of any user inactivity that could cause data loss, unless the data is preserved for more than 20 hours when the user does not take any actions. Note Privacy regulations may require explicit user consent before user identification has been authenticated and before user data is preserved. In cases where the user is a minor, explicit consent may not be solicited in most jurisdictions, countries or regions. Consultation with privacy professionals and legal counsel is advised when considering data preservation as an approach to satisfy this success criterion."},{"id":"sc-title-three-flashes-or-below-threshold","type":"mcq","skill":"recognition","scId":"three-flashes-or-below-threshold","prompt":"Which success criterion matches: Three Flashes or Below Threshold?","answer":"2.3.1","choices":["2.3.1","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-three-flashes-or-below-threshold","type":"mcq","skill":"classification","scId":"three-flashes-or-below-threshold","prompt":"What conformance level is 2.3.1 Three Flashes or Below Threshold?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-three-flashes-or-below-threshold","type":"mcq","skill":"classification","scId":"three-flashes-or-below-threshold","prompt":"Which principle includes 2.3.1 Three Flashes or Below Threshold?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-three-flashes-or-below-threshold","type":"typed","skill":"recall","scId":"three-flashes-or-below-threshold","prompt":"Type the key requirement for 2.3.1 Three Flashes or Below Threshold.","answer":"Web pages do not contain anything that flashes more than three times in any one second period, or the flash is below the general flash and red flash thresholds . Note Since any content that does not meet this success criterion can interfere with a user's ability to use the whole page, all content on the web page (whether it is used to meet other success criteria or not) must meet this success criterion. See Conformance Requirement 5: Non-Interference ."},{"id":"sc-title-three-flashes","type":"mcq","skill":"recognition","scId":"three-flashes","prompt":"Which success criterion matches: Three Flashes?","answer":"2.3.2","choices":["2.3.2","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-three-flashes","type":"mcq","skill":"classification","scId":"three-flashes","prompt":"What conformance level is 2.3.2 Three Flashes?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-three-flashes","type":"mcq","skill":"classification","scId":"three-flashes","prompt":"Which principle includes 2.3.2 Three Flashes?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-three-flashes","type":"typed","skill":"recall","scId":"three-flashes","prompt":"Type the key requirement for 2.3.2 Three Flashes.","answer":"Web pages do not contain anything that flashes more than three times in any one second period."},{"id":"sc-title-animation-from-interactions","type":"mcq","skill":"recognition","scId":"animation-from-interactions","prompt":"Which success criterion matches: Animation from Interactions?","answer":"2.3.3","choices":["2.3.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-animation-from-interactions","type":"mcq","skill":"classification","scId":"animation-from-interactions","prompt":"What conformance level is 2.3.3 Animation from Interactions?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-animation-from-interactions","type":"mcq","skill":"classification","scId":"animation-from-interactions","prompt":"Which principle includes 2.3.3 Animation from Interactions?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-animation-from-interactions","type":"typed","skill":"recall","scId":"animation-from-interactions","prompt":"Type the key requirement for 2.3.3 Animation from Interactions.","answer":"Motion animation triggered by interaction can be disabled, unless the animation is essential to the functionality or the information being conveyed."},{"id":"sc-title-bypass-blocks","type":"mcq","skill":"recognition","scId":"bypass-blocks","prompt":"Which success criterion matches: Bypass Blocks?","answer":"2.4.1","choices":["2.4.1","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-bypass-blocks","type":"mcq","skill":"classification","scId":"bypass-blocks","prompt":"What conformance level is 2.4.1 Bypass Blocks?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-bypass-blocks","type":"mcq","skill":"classification","scId":"bypass-blocks","prompt":"Which principle includes 2.4.1 Bypass Blocks?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-bypass-blocks","type":"typed","skill":"recall","scId":"bypass-blocks","prompt":"Type the key requirement for 2.4.1 Bypass Blocks.","answer":"A mechanism is available to bypass blocks of content that are repeated on multiple web pages ."},{"id":"sc-title-page-titled","type":"mcq","skill":"recognition","scId":"page-titled","prompt":"Which success criterion matches: Page Titled?","answer":"2.4.2","choices":["2.4.2","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-page-titled","type":"mcq","skill":"classification","scId":"page-titled","prompt":"What conformance level is 2.4.2 Page Titled?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-page-titled","type":"mcq","skill":"classification","scId":"page-titled","prompt":"Which principle includes 2.4.2 Page Titled?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-page-titled","type":"typed","skill":"recall","scId":"page-titled","prompt":"Type the key requirement for 2.4.2 Page Titled.","answer":"Web pages have titles that describe topic or purpose."},{"id":"sc-title-focus-order","type":"mcq","skill":"recognition","scId":"focus-order","prompt":"Which success criterion matches: Focus Order?","answer":"2.4.3","choices":["2.4.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-focus-order","type":"mcq","skill":"classification","scId":"focus-order","prompt":"What conformance level is 2.4.3 Focus Order?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-focus-order","type":"mcq","skill":"classification","scId":"focus-order","prompt":"Which principle includes 2.4.3 Focus Order?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-focus-order","type":"typed","skill":"recall","scId":"focus-order","prompt":"Type the key requirement for 2.4.3 Focus Order.","answer":"If a web page can be navigated sequentially and the navigation sequences affect meaning or operation, focusable components receive focus in an order that preserves meaning and operability."},{"id":"sc-title-link-purpose-in-context","type":"mcq","skill":"recognition","scId":"link-purpose-in-context","prompt":"Which success criterion matches: Link Purpose (In Context)?","answer":"2.4.4","choices":["2.4.4","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-link-purpose-in-context","type":"mcq","skill":"classification","scId":"link-purpose-in-context","prompt":"What conformance level is 2.4.4 Link Purpose (In Context)?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-link-purpose-in-context","type":"mcq","skill":"classification","scId":"link-purpose-in-context","prompt":"Which principle includes 2.4.4 Link Purpose (In Context)?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-link-purpose-in-context","type":"typed","skill":"recall","scId":"link-purpose-in-context","prompt":"Type the key requirement for 2.4.4 Link Purpose (In Context).","answer":"The purpose of each link can be determined from the link text alone or from the link text together with its programmatically determined link context , except where the purpose of the link would be ambiguous to users in general ."},{"id":"sc-title-multiple-ways","type":"mcq","skill":"recognition","scId":"multiple-ways","prompt":"Which success criterion matches: Multiple Ways?","answer":"2.4.5","choices":["2.4.5","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-multiple-ways","type":"mcq","skill":"classification","scId":"multiple-ways","prompt":"What conformance level is 2.4.5 Multiple Ways?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-multiple-ways","type":"mcq","skill":"classification","scId":"multiple-ways","prompt":"Which principle includes 2.4.5 Multiple Ways?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-multiple-ways","type":"typed","skill":"recall","scId":"multiple-ways","prompt":"Type the key requirement for 2.4.5 Multiple Ways.","answer":"More than one way is available to locate a web page within a set of web pages except where the web page is the result of, or a step in, a process ."},{"id":"sc-title-headings-and-labels","type":"mcq","skill":"recognition","scId":"headings-and-labels","prompt":"Which success criterion matches: Headings and Labels?","answer":"2.4.6","choices":["2.4.6","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-headings-and-labels","type":"mcq","skill":"classification","scId":"headings-and-labels","prompt":"What conformance level is 2.4.6 Headings and Labels?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-headings-and-labels","type":"mcq","skill":"classification","scId":"headings-and-labels","prompt":"Which principle includes 2.4.6 Headings and Labels?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-headings-and-labels","type":"typed","skill":"recall","scId":"headings-and-labels","prompt":"Type the key requirement for 2.4.6 Headings and Labels.","answer":"Headings and labels describe topic or purpose."},{"id":"sc-title-focus-visible","type":"mcq","skill":"recognition","scId":"focus-visible","prompt":"Which success criterion matches: Focus Visible?","answer":"2.4.7","choices":["2.4.7","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-focus-visible","type":"mcq","skill":"classification","scId":"focus-visible","prompt":"What conformance level is 2.4.7 Focus Visible?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-focus-visible","type":"mcq","skill":"classification","scId":"focus-visible","prompt":"Which principle includes 2.4.7 Focus Visible?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-focus-visible","type":"typed","skill":"recall","scId":"focus-visible","prompt":"Type the key requirement for 2.4.7 Focus Visible.","answer":"Any keyboard operable user interface has a mode of operation where the keyboard focus indicator is visible."},{"id":"sc-title-location","type":"mcq","skill":"recognition","scId":"location","prompt":"Which success criterion matches: Location?","answer":"2.4.8","choices":["2.4.8","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-location","type":"mcq","skill":"classification","scId":"location","prompt":"What conformance level is 2.4.8 Location?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-location","type":"mcq","skill":"classification","scId":"location","prompt":"Which principle includes 2.4.8 Location?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-location","type":"typed","skill":"recall","scId":"location","prompt":"Type the key requirement for 2.4.8 Location.","answer":"Information about the user's location within a set of web pages is available."},{"id":"sc-title-link-purpose-link-only","type":"mcq","skill":"recognition","scId":"link-purpose-link-only","prompt":"Which success criterion matches: Link Purpose (Link Only)?","answer":"2.4.9","choices":["2.4.9","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-link-purpose-link-only","type":"mcq","skill":"classification","scId":"link-purpose-link-only","prompt":"What conformance level is 2.4.9 Link Purpose (Link Only)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-link-purpose-link-only","type":"mcq","skill":"classification","scId":"link-purpose-link-only","prompt":"Which principle includes 2.4.9 Link Purpose (Link Only)?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-link-purpose-link-only","type":"typed","skill":"recall","scId":"link-purpose-link-only","prompt":"Type the key requirement for 2.4.9 Link Purpose (Link Only).","answer":"A mechanism is available to allow the purpose of each link to be identified from link text alone, except where the purpose of the link would be ambiguous to users in general ."},{"id":"sc-title-section-headings","type":"mcq","skill":"recognition","scId":"section-headings","prompt":"Which success criterion matches: Section Headings?","answer":"2.4.10","choices":["2.4.10","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-section-headings","type":"mcq","skill":"classification","scId":"section-headings","prompt":"What conformance level is 2.4.10 Section Headings?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-section-headings","type":"mcq","skill":"classification","scId":"section-headings","prompt":"Which principle includes 2.4.10 Section Headings?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-section-headings","type":"typed","skill":"recall","scId":"section-headings","prompt":"Type the key requirement for 2.4.10 Section Headings.","answer":"Section headings are used to organize the content. Note 1 \\"Heading\\" is used in its general sense and includes titles and other ways to add a heading to different types of content. Note 2 This success criterion covers sections within writing, not user interface components . User interface components are covered under Success Criterion 4.1.2 ."},{"id":"sc-title-focus-not-obscured-minimum","type":"mcq","skill":"recognition","scId":"focus-not-obscured-minimum","prompt":"Which success criterion matches: Focus Not Obscured (Minimum)?","answer":"2.4.11","choices":["2.4.11","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-focus-not-obscured-minimum","type":"mcq","skill":"classification","scId":"focus-not-obscured-minimum","prompt":"What conformance level is 2.4.11 Focus Not Obscured (Minimum)?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-focus-not-obscured-minimum","type":"mcq","skill":"classification","scId":"focus-not-obscured-minimum","prompt":"Which principle includes 2.4.11 Focus Not Obscured (Minimum)?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-focus-not-obscured-minimum","type":"typed","skill":"recall","scId":"focus-not-obscured-minimum","prompt":"Type the key requirement for 2.4.11 Focus Not Obscured (Minimum).","answer":"When a user interface component receives keyboard focus, the component is not entirely hidden due to author-created content. Note 1 Where content in a configurable interface can be repositioned by the user, then only the initial positions of user-movable content are considered for testing and conformance of this success criterion. Note 2 Content opened by the user may obscure the component receiving focus. If the user can reveal the focused component without advancing the keyboard focus, the component with focus is not considered visually hidden due to author-created content."},{"id":"sc-title-focus-not-obscured-enhanced","type":"mcq","skill":"recognition","scId":"focus-not-obscured-enhanced","prompt":"Which success criterion matches: Focus Not Obscured (Enhanced)?","answer":"2.4.12","choices":["2.4.12","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-focus-not-obscured-enhanced","type":"mcq","skill":"classification","scId":"focus-not-obscured-enhanced","prompt":"What conformance level is 2.4.12 Focus Not Obscured (Enhanced)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-focus-not-obscured-enhanced","type":"mcq","skill":"classification","scId":"focus-not-obscured-enhanced","prompt":"Which principle includes 2.4.12 Focus Not Obscured (Enhanced)?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-focus-not-obscured-enhanced","type":"typed","skill":"recall","scId":"focus-not-obscured-enhanced","prompt":"Type the key requirement for 2.4.12 Focus Not Obscured (Enhanced).","answer":"When a user interface component receives keyboard focus, no part of the component is hidden by author-created content."},{"id":"sc-title-focus-appearance","type":"mcq","skill":"recognition","scId":"focus-appearance","prompt":"Which success criterion matches: Focus Appearance?","answer":"2.4.13","choices":["2.4.13","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-focus-appearance","type":"mcq","skill":"classification","scId":"focus-appearance","prompt":"What conformance level is 2.4.13 Focus Appearance?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-focus-appearance","type":"mcq","skill":"classification","scId":"focus-appearance","prompt":"Which principle includes 2.4.13 Focus Appearance?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-focus-appearance","type":"typed","skill":"recall","scId":"focus-appearance","prompt":"Type the key requirement for 2.4.13 Focus Appearance.","answer":"When the keyboard focus indicator is visible, an area of the focus indicator meets all the following: is at least as large as the area of a 2 CSS pixel thick perimeter of the unfocused component or sub-component, and has a contrast ratio of at least 3:1 between the same pixels in the focused and unfocused states. Exceptions: The focus indicator is determined by the user agent and cannot be adjusted by the author, or The focus indicator and the indicator's background color are not modified by the author. Note 1 What is perceived as the user interface component or sub-component (to determine the perimeter) depends on its visual presentation . The visual presentation includes the component's visible content , border, and component-specific background. It does not include shadow and glow effects outside the component's content, background, or border. Note 2 Examples of sub-components that may receive a focus indicator are menu items in an opened drop-down menu, or focusable cells in a grid. Note 3 Contrast calculations can be based on colors defined within the technology (such as HTML , CSS, and SVG). Pixels modified by user agent resolution enhancements and anti-aliasing can be ignored."},{"id":"sc-title-pointer-gestures","type":"mcq","skill":"recognition","scId":"pointer-gestures","prompt":"Which success criterion matches: Pointer Gestures?","answer":"2.5.1","choices":["2.5.1","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-pointer-gestures","type":"mcq","skill":"classification","scId":"pointer-gestures","prompt":"What conformance level is 2.5.1 Pointer Gestures?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-pointer-gestures","type":"mcq","skill":"classification","scId":"pointer-gestures","prompt":"Which principle includes 2.5.1 Pointer Gestures?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-pointer-gestures","type":"typed","skill":"recall","scId":"pointer-gestures","prompt":"Type the key requirement for 2.5.1 Pointer Gestures.","answer":"All functionality that uses multipoint or path-based gestures for operation can be operated with a single pointer without a path-based gesture, unless a multipoint or path-based gesture is essential . Note This requirement applies to web content that interprets pointer actions (i.e., this does not apply to actions that are required to operate the user agent or assistive technology)."},{"id":"sc-title-pointer-cancellation","type":"mcq","skill":"recognition","scId":"pointer-cancellation","prompt":"Which success criterion matches: Pointer Cancellation?","answer":"2.5.2","choices":["2.5.2","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-pointer-cancellation","type":"mcq","skill":"classification","scId":"pointer-cancellation","prompt":"What conformance level is 2.5.2 Pointer Cancellation?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-pointer-cancellation","type":"mcq","skill":"classification","scId":"pointer-cancellation","prompt":"Which principle includes 2.5.2 Pointer Cancellation?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-pointer-cancellation","type":"typed","skill":"recall","scId":"pointer-cancellation","prompt":"Type the key requirement for 2.5.2 Pointer Cancellation.","answer":"For functionality that can be operated using a single pointer , at least one of the following is true: No Down-Event The down-event of the pointer is not used to execute any part of the function; Abort or Undo Completion of the function is on the up-event , and a mechanism is available to abort the function before completion or to undo the function after completion; Up Reversal The up-event reverses any outcome of the preceding down-event; Essential Completing the function on the down-event is essential . Note 1 Functions that emulate a keyboard or numeric keypad key press are considered essential. Note 2 This requirement applies to web content that interprets pointer actions (i.e., this does not apply to actions that are required to operate the user agent or assistive technology)."},{"id":"sc-title-label-in-name","type":"mcq","skill":"recognition","scId":"label-in-name","prompt":"Which success criterion matches: Label in Name?","answer":"2.5.3","choices":["2.5.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-label-in-name","type":"mcq","skill":"classification","scId":"label-in-name","prompt":"What conformance level is 2.5.3 Label in Name?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-label-in-name","type":"mcq","skill":"classification","scId":"label-in-name","prompt":"Which principle includes 2.5.3 Label in Name?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-label-in-name","type":"typed","skill":"recall","scId":"label-in-name","prompt":"Type the key requirement for 2.5.3 Label in Name.","answer":"For user interface components with labels that include text or images of text , the name contains the text that is presented visually. Note A best practice is to have the text of the label at the start of the name."},{"id":"sc-title-motion-actuation","type":"mcq","skill":"recognition","scId":"motion-actuation","prompt":"Which success criterion matches: Motion Actuation?","answer":"2.5.4","choices":["2.5.4","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-motion-actuation","type":"mcq","skill":"classification","scId":"motion-actuation","prompt":"What conformance level is 2.5.4 Motion Actuation?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-motion-actuation","type":"mcq","skill":"classification","scId":"motion-actuation","prompt":"Which principle includes 2.5.4 Motion Actuation?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-motion-actuation","type":"typed","skill":"recall","scId":"motion-actuation","prompt":"Type the key requirement for 2.5.4 Motion Actuation.","answer":"Functionality that can be operated by device motion or user motion can also be operated by user interface components and responding to the motion can be disabled to prevent accidental actuation, except when: Supported Interface The motion is used to operate functionality through an accessibility supported interface; Essential The motion is essential for the function and doing so would invalidate the activity."},{"id":"sc-title-target-size-enhanced","type":"mcq","skill":"recognition","scId":"target-size-enhanced","prompt":"Which success criterion matches: Target Size (Enhanced)?","answer":"2.5.5","choices":["2.5.5","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-target-size-enhanced","type":"mcq","skill":"classification","scId":"target-size-enhanced","prompt":"What conformance level is 2.5.5 Target Size (Enhanced)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-target-size-enhanced","type":"mcq","skill":"classification","scId":"target-size-enhanced","prompt":"Which principle includes 2.5.5 Target Size (Enhanced)?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-target-size-enhanced","type":"typed","skill":"recall","scId":"target-size-enhanced","prompt":"Type the key requirement for 2.5.5 Target Size (Enhanced).","answer":"The size of the target for pointer inputs is at least 44 by 44 CSS pixels except when: Equivalent The target is available through an equivalent link or control on the same page that is at least 44 by 44 CSS pixels; Inline The target is in a sentence or block of text ; User Agent Control The size of the target is determined by the user agent and is not modified by the author; Essential A particular presentation of the target is essential to the information being conveyed."},{"id":"sc-title-concurrent-input-mechanisms","type":"mcq","skill":"recognition","scId":"concurrent-input-mechanisms","prompt":"Which success criterion matches: Concurrent Input Mechanisms?","answer":"2.5.6","choices":["2.5.6","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-concurrent-input-mechanisms","type":"mcq","skill":"classification","scId":"concurrent-input-mechanisms","prompt":"What conformance level is 2.5.6 Concurrent Input Mechanisms?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-concurrent-input-mechanisms","type":"mcq","skill":"classification","scId":"concurrent-input-mechanisms","prompt":"Which principle includes 2.5.6 Concurrent Input Mechanisms?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-concurrent-input-mechanisms","type":"typed","skill":"recall","scId":"concurrent-input-mechanisms","prompt":"Type the key requirement for 2.5.6 Concurrent Input Mechanisms.","answer":"Web content does not restrict use of input modalities available on a platform except where the restriction is essential , required to ensure the security of the content, or required to respect user settings."},{"id":"sc-title-dragging-movements","type":"mcq","skill":"recognition","scId":"dragging-movements","prompt":"Which success criterion matches: Dragging Movements?","answer":"2.5.7","choices":["2.5.7","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-dragging-movements","type":"mcq","skill":"classification","scId":"dragging-movements","prompt":"What conformance level is 2.5.7 Dragging Movements?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-dragging-movements","type":"mcq","skill":"classification","scId":"dragging-movements","prompt":"Which principle includes 2.5.7 Dragging Movements?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-dragging-movements","type":"typed","skill":"recall","scId":"dragging-movements","prompt":"Type the key requirement for 2.5.7 Dragging Movements.","answer":"All functionality that uses a dragging movement for operation can be achieved by a single pointer without dragging, unless dragging is essential or the functionality is determined by the user agent and not modified by the author. Note This requirement applies to web content that interprets pointer actions (i.e., this does not apply to actions that are required to operate the user agent or assistive technology)."},{"id":"sc-title-target-size-minimum","type":"mcq","skill":"recognition","scId":"target-size-minimum","prompt":"Which success criterion matches: Target Size (Minimum)?","answer":"2.5.8","choices":["2.5.8","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-target-size-minimum","type":"mcq","skill":"classification","scId":"target-size-minimum","prompt":"What conformance level is 2.5.8 Target Size (Minimum)?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-target-size-minimum","type":"mcq","skill":"classification","scId":"target-size-minimum","prompt":"Which principle includes 2.5.8 Target Size (Minimum)?","answer":"Operable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-target-size-minimum","type":"typed","skill":"recall","scId":"target-size-minimum","prompt":"Type the key requirement for 2.5.8 Target Size (Minimum).","answer":"The size of the target for pointer inputs is at least 24 by 24 CSS pixels , except when: Spacing Undersized targets (those less than 24 by 24 CSS pixels) are positioned so that if a 24 CSS pixel diameter circle is centered on the bounding box of each, the circles do not intersect another target or the circle for another undersized target; Equivalent The function can be achieved through a different control on the same page that meets this criterion; Inline The target is in a sentence or its size is otherwise constrained by the line-height of non-target text; User Agent Control The size of the target is determined by the user agent and is not modified by the author; Essential A particular presentation of the target is essential or is legally required for the information being conveyed. Note 1 Targets that allow for values to be selected spatially based on position within the target are considered one target for the purpose of the success criterion. Examples include sliders, color pickers displaying a gradient of colors, or editable areas where you position the cursor. Note 2 For inline targets the line-height should be interpreted as perpendicular to the flow of text. For example, in a language displayed vertically, the line-height would be horizontal."},{"id":"sc-title-language-of-page","type":"mcq","skill":"recognition","scId":"language-of-page","prompt":"Which success criterion matches: Language of Page?","answer":"3.1.1","choices":["3.1.1","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-language-of-page","type":"mcq","skill":"classification","scId":"language-of-page","prompt":"What conformance level is 3.1.1 Language of Page?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-language-of-page","type":"mcq","skill":"classification","scId":"language-of-page","prompt":"Which principle includes 3.1.1 Language of Page?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-language-of-page","type":"typed","skill":"recall","scId":"language-of-page","prompt":"Type the key requirement for 3.1.1 Language of Page.","answer":"The default human language of each web page can be programmatically determined ."},{"id":"sc-title-language-of-parts","type":"mcq","skill":"recognition","scId":"language-of-parts","prompt":"Which success criterion matches: Language of Parts?","answer":"3.1.2","choices":["3.1.2","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-language-of-parts","type":"mcq","skill":"classification","scId":"language-of-parts","prompt":"What conformance level is 3.1.2 Language of Parts?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-language-of-parts","type":"mcq","skill":"classification","scId":"language-of-parts","prompt":"Which principle includes 3.1.2 Language of Parts?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-language-of-parts","type":"typed","skill":"recall","scId":"language-of-parts","prompt":"Type the key requirement for 3.1.2 Language of Parts.","answer":"The human language of each passage or phrase in the content can be programmatically determined except for proper names, technical terms, words of indeterminate language, and words or phrases that have become part of the vernacular of the immediately surrounding text ."},{"id":"sc-title-unusual-words","type":"mcq","skill":"recognition","scId":"unusual-words","prompt":"Which success criterion matches: Unusual Words?","answer":"3.1.3","choices":["3.1.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-unusual-words","type":"mcq","skill":"classification","scId":"unusual-words","prompt":"What conformance level is 3.1.3 Unusual Words?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-unusual-words","type":"mcq","skill":"classification","scId":"unusual-words","prompt":"Which principle includes 3.1.3 Unusual Words?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-unusual-words","type":"typed","skill":"recall","scId":"unusual-words","prompt":"Type the key requirement for 3.1.3 Unusual Words.","answer":"A mechanism is available for identifying specific definitions of words or phrases used in an unusual or restricted way , including idioms and jargon ."},{"id":"sc-title-abbreviations","type":"mcq","skill":"recognition","scId":"abbreviations","prompt":"Which success criterion matches: Abbreviations?","answer":"3.1.4","choices":["3.1.4","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-abbreviations","type":"mcq","skill":"classification","scId":"abbreviations","prompt":"What conformance level is 3.1.4 Abbreviations?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-abbreviations","type":"mcq","skill":"classification","scId":"abbreviations","prompt":"Which principle includes 3.1.4 Abbreviations?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-abbreviations","type":"typed","skill":"recall","scId":"abbreviations","prompt":"Type the key requirement for 3.1.4 Abbreviations.","answer":"A mechanism for identifying the expanded form or meaning of abbreviations is available."},{"id":"sc-title-reading-level","type":"mcq","skill":"recognition","scId":"reading-level","prompt":"Which success criterion matches: Reading Level?","answer":"3.1.5","choices":["3.1.5","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-reading-level","type":"mcq","skill":"classification","scId":"reading-level","prompt":"What conformance level is 3.1.5 Reading Level?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-reading-level","type":"mcq","skill":"classification","scId":"reading-level","prompt":"Which principle includes 3.1.5 Reading Level?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-reading-level","type":"typed","skill":"recall","scId":"reading-level","prompt":"Type the key requirement for 3.1.5 Reading Level.","answer":"When text requires reading ability more advanced than the lower secondary education level after removal of proper names and titles, supplemental content , or a version that does not require reading ability more advanced than the lower secondary education level, is available."},{"id":"sc-title-pronunciation","type":"mcq","skill":"recognition","scId":"pronunciation","prompt":"Which success criterion matches: Pronunciation?","answer":"3.1.6","choices":["3.1.6","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-pronunciation","type":"mcq","skill":"classification","scId":"pronunciation","prompt":"What conformance level is 3.1.6 Pronunciation?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-pronunciation","type":"mcq","skill":"classification","scId":"pronunciation","prompt":"Which principle includes 3.1.6 Pronunciation?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-pronunciation","type":"typed","skill":"recall","scId":"pronunciation","prompt":"Type the key requirement for 3.1.6 Pronunciation.","answer":"A mechanism is available for identifying specific pronunciation of words where meaning of the words, in context, is ambiguous without knowing the pronunciation."},{"id":"sc-title-on-focus","type":"mcq","skill":"recognition","scId":"on-focus","prompt":"Which success criterion matches: On Focus?","answer":"3.2.1","choices":["3.2.1","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-on-focus","type":"mcq","skill":"classification","scId":"on-focus","prompt":"What conformance level is 3.2.1 On Focus?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-on-focus","type":"mcq","skill":"classification","scId":"on-focus","prompt":"Which principle includes 3.2.1 On Focus?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-on-focus","type":"typed","skill":"recall","scId":"on-focus","prompt":"Type the key requirement for 3.2.1 On Focus.","answer":"When any user interface component receives focus, it does not initiate a change of context ."},{"id":"sc-title-on-input","type":"mcq","skill":"recognition","scId":"on-input","prompt":"Which success criterion matches: On Input?","answer":"3.2.2","choices":["3.2.2","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-on-input","type":"mcq","skill":"classification","scId":"on-input","prompt":"What conformance level is 3.2.2 On Input?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-on-input","type":"mcq","skill":"classification","scId":"on-input","prompt":"Which principle includes 3.2.2 On Input?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-on-input","type":"typed","skill":"recall","scId":"on-input","prompt":"Type the key requirement for 3.2.2 On Input.","answer":"Changing the setting of any user interface component does not automatically cause a change of context unless the user has been advised of the behavior before using the component."},{"id":"sc-title-consistent-navigation","type":"mcq","skill":"recognition","scId":"consistent-navigation","prompt":"Which success criterion matches: Consistent Navigation?","answer":"3.2.3","choices":["3.2.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-consistent-navigation","type":"mcq","skill":"classification","scId":"consistent-navigation","prompt":"What conformance level is 3.2.3 Consistent Navigation?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-consistent-navigation","type":"mcq","skill":"classification","scId":"consistent-navigation","prompt":"Which principle includes 3.2.3 Consistent Navigation?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-consistent-navigation","type":"typed","skill":"recall","scId":"consistent-navigation","prompt":"Type the key requirement for 3.2.3 Consistent Navigation.","answer":"Navigational mechanisms that are repeated on multiple web pages within a set of web pages occur in the same relative order each time they are repeated, unless a change is initiated by the user."},{"id":"sc-title-consistent-identification","type":"mcq","skill":"recognition","scId":"consistent-identification","prompt":"Which success criterion matches: Consistent Identification?","answer":"3.2.4","choices":["3.2.4","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-consistent-identification","type":"mcq","skill":"classification","scId":"consistent-identification","prompt":"What conformance level is 3.2.4 Consistent Identification?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-consistent-identification","type":"mcq","skill":"classification","scId":"consistent-identification","prompt":"Which principle includes 3.2.4 Consistent Identification?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-consistent-identification","type":"typed","skill":"recall","scId":"consistent-identification","prompt":"Type the key requirement for 3.2.4 Consistent Identification.","answer":"Components that have the same functionality within a set of web pages are identified consistently."},{"id":"sc-title-change-on-request","type":"mcq","skill":"recognition","scId":"change-on-request","prompt":"Which success criterion matches: Change on Request?","answer":"3.2.5","choices":["3.2.5","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-change-on-request","type":"mcq","skill":"classification","scId":"change-on-request","prompt":"What conformance level is 3.2.5 Change on Request?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-change-on-request","type":"mcq","skill":"classification","scId":"change-on-request","prompt":"Which principle includes 3.2.5 Change on Request?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-change-on-request","type":"typed","skill":"recall","scId":"change-on-request","prompt":"Type the key requirement for 3.2.5 Change on Request.","answer":"Changes of context are initiated only by user request or a mechanism is available to turn off such changes."},{"id":"sc-title-consistent-help","type":"mcq","skill":"recognition","scId":"consistent-help","prompt":"Which success criterion matches: Consistent Help?","answer":"3.2.6","choices":["3.2.6","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-consistent-help","type":"mcq","skill":"classification","scId":"consistent-help","prompt":"What conformance level is 3.2.6 Consistent Help?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-consistent-help","type":"mcq","skill":"classification","scId":"consistent-help","prompt":"Which principle includes 3.2.6 Consistent Help?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-consistent-help","type":"typed","skill":"recall","scId":"consistent-help","prompt":"Type the key requirement for 3.2.6 Consistent Help.","answer":"If a web page contains any of the following help mechanisms , and those mechanisms are repeated on multiple web pages within a set of web pages , they occur in the same order relative to other page content, unless a change is initiated by the user: Human contact details; Human contact mechanism; Self-help option; A fully automated contact mechanism. Note 1 Help mechanisms may be provided directly on the page, or may be provided via a direct link to a different page containing the information. Note 2 For this success criterion, \\"the same order relative to other page content\\" can be thought of as how the content is ordered when the page is serialized. The visual position of a help mechanism is likely to be consistent across pages for the same page variation (e.g., CSS break-point). The user can initiate a change, such as changing the page's zoom or orientation, which may trigger a different page variation. This criterion is concerned with relative order across pages displayed in the same page variation (e.g., same zoom level and orientation)."},{"id":"sc-title-error-identification","type":"mcq","skill":"recognition","scId":"error-identification","prompt":"Which success criterion matches: Error Identification?","answer":"3.3.1","choices":["3.3.1","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-error-identification","type":"mcq","skill":"classification","scId":"error-identification","prompt":"What conformance level is 3.3.1 Error Identification?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-error-identification","type":"mcq","skill":"classification","scId":"error-identification","prompt":"Which principle includes 3.3.1 Error Identification?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-error-identification","type":"typed","skill":"recall","scId":"error-identification","prompt":"Type the key requirement for 3.3.1 Error Identification.","answer":"If an input error is automatically detected, the item that is in error is identified and the error is described to the user in text."},{"id":"sc-title-labels-or-instructions","type":"mcq","skill":"recognition","scId":"labels-or-instructions","prompt":"Which success criterion matches: Labels or Instructions?","answer":"3.3.2","choices":["3.3.2","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-labels-or-instructions","type":"mcq","skill":"classification","scId":"labels-or-instructions","prompt":"What conformance level is 3.3.2 Labels or Instructions?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-labels-or-instructions","type":"mcq","skill":"classification","scId":"labels-or-instructions","prompt":"Which principle includes 3.3.2 Labels or Instructions?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-labels-or-instructions","type":"typed","skill":"recall","scId":"labels-or-instructions","prompt":"Type the key requirement for 3.3.2 Labels or Instructions.","answer":"Labels or instructions are provided when content requires user input."},{"id":"sc-title-error-suggestion","type":"mcq","skill":"recognition","scId":"error-suggestion","prompt":"Which success criterion matches: Error Suggestion?","answer":"3.3.3","choices":["3.3.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-error-suggestion","type":"mcq","skill":"classification","scId":"error-suggestion","prompt":"What conformance level is 3.3.3 Error Suggestion?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-error-suggestion","type":"mcq","skill":"classification","scId":"error-suggestion","prompt":"Which principle includes 3.3.3 Error Suggestion?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-error-suggestion","type":"typed","skill":"recall","scId":"error-suggestion","prompt":"Type the key requirement for 3.3.3 Error Suggestion.","answer":"If an input error is automatically detected and suggestions for correction are known, then the suggestions are provided to the user, unless it would jeopardize the security or purpose of the content."},{"id":"sc-title-error-prevention-legal-financial-data","type":"mcq","skill":"recognition","scId":"error-prevention-legal-financial-data","prompt":"Which success criterion matches: Error Prevention (Legal, Financial, Data)?","answer":"3.3.4","choices":["3.3.4","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-error-prevention-legal-financial-data","type":"mcq","skill":"classification","scId":"error-prevention-legal-financial-data","prompt":"What conformance level is 3.3.4 Error Prevention (Legal, Financial, Data)?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-error-prevention-legal-financial-data","type":"mcq","skill":"classification","scId":"error-prevention-legal-financial-data","prompt":"Which principle includes 3.3.4 Error Prevention (Legal, Financial, Data)?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-error-prevention-legal-financial-data","type":"typed","skill":"recall","scId":"error-prevention-legal-financial-data","prompt":"Type the key requirement for 3.3.4 Error Prevention (Legal, Financial, Data).","answer":"For web pages that cause legal commitments or financial transactions for the user to occur, that modify or delete user-controllable data in data storage systems, or that submit user test responses, at least one of the following is true: Reversible Submissions are reversible. Checked Data entered by the user is checked for input errors and the user is provided an opportunity to correct them. Confirmed A mechanism is available for reviewing, confirming, and correcting information before finalizing the submission."},{"id":"sc-title-help","type":"mcq","skill":"recognition","scId":"help","prompt":"Which success criterion matches: Help?","answer":"3.3.5","choices":["3.3.5","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-help","type":"mcq","skill":"classification","scId":"help","prompt":"What conformance level is 3.3.5 Help?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-help","type":"mcq","skill":"classification","scId":"help","prompt":"Which principle includes 3.3.5 Help?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-help","type":"typed","skill":"recall","scId":"help","prompt":"Type the key requirement for 3.3.5 Help.","answer":"Context-sensitive help is available."},{"id":"sc-title-error-prevention-all","type":"mcq","skill":"recognition","scId":"error-prevention-all","prompt":"Which success criterion matches: Error Prevention (All)?","answer":"3.3.6","choices":["3.3.6","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-error-prevention-all","type":"mcq","skill":"classification","scId":"error-prevention-all","prompt":"What conformance level is 3.3.6 Error Prevention (All)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-error-prevention-all","type":"mcq","skill":"classification","scId":"error-prevention-all","prompt":"Which principle includes 3.3.6 Error Prevention (All)?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-error-prevention-all","type":"typed","skill":"recall","scId":"error-prevention-all","prompt":"Type the key requirement for 3.3.6 Error Prevention (All).","answer":"For web pages that require the user to submit information, at least one of the following is true: Reversible Submissions are reversible. Checked Data entered by the user is checked for input errors and the user is provided an opportunity to correct them. Confirmed A mechanism is available for reviewing, confirming, and correcting information before finalizing the submission."},{"id":"sc-title-redundant-entry","type":"mcq","skill":"recognition","scId":"redundant-entry","prompt":"Which success criterion matches: Redundant Entry?","answer":"3.3.7","choices":["3.3.7","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-redundant-entry","type":"mcq","skill":"classification","scId":"redundant-entry","prompt":"What conformance level is 3.3.7 Redundant Entry?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-redundant-entry","type":"mcq","skill":"classification","scId":"redundant-entry","prompt":"Which principle includes 3.3.7 Redundant Entry?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-redundant-entry","type":"typed","skill":"recall","scId":"redundant-entry","prompt":"Type the key requirement for 3.3.7 Redundant Entry.","answer":"Information previously entered by or provided to the user that is required to be entered again in the same process is either: auto-populated, or available for the user to select. Except when: re-entering the information is essential , the information is required to ensure the security of the content, or previously entered information is no longer valid."},{"id":"sc-title-accessible-authentication-minimum","type":"mcq","skill":"recognition","scId":"accessible-authentication-minimum","prompt":"Which success criterion matches: Accessible Authentication (Minimum)?","answer":"3.3.8","choices":["3.3.8","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-accessible-authentication-minimum","type":"mcq","skill":"classification","scId":"accessible-authentication-minimum","prompt":"What conformance level is 3.3.8 Accessible Authentication (Minimum)?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-accessible-authentication-minimum","type":"mcq","skill":"classification","scId":"accessible-authentication-minimum","prompt":"Which principle includes 3.3.8 Accessible Authentication (Minimum)?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-accessible-authentication-minimum","type":"typed","skill":"recall","scId":"accessible-authentication-minimum","prompt":"Type the key requirement for 3.3.8 Accessible Authentication (Minimum).","answer":"A cognitive function test (such as remembering a password or solving a puzzle) is not required for any step in an authentication process unless that step provides at least one of the following: Alternative Another authentication method that does not rely on a cognitive function test. Mechanism A mechanism is available to assist the user in completing the cognitive function test. Object Recognition The cognitive function test is to recognize objects. Personal Content The cognitive function test is to identify non-text content the user provided to the website. Note 1 \\"Object recognition\\" and \\"Personal content\\" may be represented by images, video, or audio. Note 2 Examples of mechanisms that satisfy this criterion include: support for password entry by password managers to reduce memory need, and copy and paste to reduce the cognitive burden of re-typing."},{"id":"sc-title-accessible-authentication-enhanced","type":"mcq","skill":"recognition","scId":"accessible-authentication-enhanced","prompt":"Which success criterion matches: Accessible Authentication (Enhanced)?","answer":"3.3.9","choices":["3.3.9","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-accessible-authentication-enhanced","type":"mcq","skill":"classification","scId":"accessible-authentication-enhanced","prompt":"What conformance level is 3.3.9 Accessible Authentication (Enhanced)?","answer":"AAA","choices":["A","AA","AAA"]},{"id":"sc-principle-accessible-authentication-enhanced","type":"mcq","skill":"classification","scId":"accessible-authentication-enhanced","prompt":"Which principle includes 3.3.9 Accessible Authentication (Enhanced)?","answer":"Understandable","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-accessible-authentication-enhanced","type":"typed","skill":"recall","scId":"accessible-authentication-enhanced","prompt":"Type the key requirement for 3.3.9 Accessible Authentication (Enhanced).","answer":"A cognitive function test (such as remembering a password or solving a puzzle) is not required for any step in an authentication process unless that step provides at least one of the following: Alternative Another authentication method that does not rely on a cognitive function test. Mechanism A mechanism is available to assist the user in completing the cognitive function test."},{"id":"sc-title-parsing","type":"mcq","skill":"recognition","scId":"parsing","prompt":"Which success criterion matches: Parsing (Obsolete and removed)?","answer":"4.1.1","choices":["4.1.1","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-parsing","type":"mcq","skill":"classification","scId":"parsing","prompt":"What conformance level is 4.1.1 Parsing (Obsolete and removed)?","answer":"","choices":["A","AA","AAA"]},{"id":"sc-principle-parsing","type":"mcq","skill":"classification","scId":"parsing","prompt":"Which principle includes 4.1.1 Parsing (Obsolete and removed)?","answer":"Robust","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-parsing","type":"typed","skill":"recall","scId":"parsing","prompt":"Type the key requirement for 4.1.1 Parsing (Obsolete and removed).","answer":"Note This criterion was originally adopted to address problems that assistive technology had directly parsing HTML . Assistive technology no longer has any need to directly parse HTML . Consequently, these problems either no longer exist or are addressed by other criteria. This criterion no longer has utility and is removed."},{"id":"sc-title-name-role-value","type":"mcq","skill":"recognition","scId":"name-role-value","prompt":"Which success criterion matches: Name, Role, Value?","answer":"4.1.2","choices":["4.1.2","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-name-role-value","type":"mcq","skill":"classification","scId":"name-role-value","prompt":"What conformance level is 4.1.2 Name, Role, Value?","answer":"A","choices":["A","AA","AAA"]},{"id":"sc-principle-name-role-value","type":"mcq","skill":"classification","scId":"name-role-value","prompt":"Which principle includes 4.1.2 Name, Role, Value?","answer":"Robust","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-name-role-value","type":"typed","skill":"recall","scId":"name-role-value","prompt":"Type the key requirement for 4.1.2 Name, Role, Value.","answer":"For all user interface components (including but not limited to: form elements, links and components generated by scripts), the name and role can be programmatically determined ; states , properties, and values that can be set by the user can be programmatically set ; and notification of changes to these items is available to user agents , including assistive technologies . Note This success criterion is primarily for web authors who develop or script their own user interface components. For example, standard HTML controls already meet this success criterion when used according to specification."},{"id":"sc-title-status-messages","type":"mcq","skill":"recognition","scId":"status-messages","prompt":"Which success criterion matches: Status Messages?","answer":"4.1.3","choices":["4.1.3","1.1.1","1.2.1","1.2.2"]},{"id":"sc-level-status-messages","type":"mcq","skill":"classification","scId":"status-messages","prompt":"What conformance level is 4.1.3 Status Messages?","answer":"AA","choices":["A","AA","AAA"]},{"id":"sc-principle-status-messages","type":"mcq","skill":"classification","scId":"status-messages","prompt":"Which principle includes 4.1.3 Status Messages?","answer":"Robust","choices":["Perceivable","Operable","Understandable","Robust"]},{"id":"sc-recall-status-messages","type":"typed","skill":"recall","scId":"status-messages","prompt":"Type the key requirement for 4.1.3 Status Messages.","answer":"In content implemented using markup languages, status messages can be programmatically determined through role or properties such that they can be presented to the user by assistive technologies without receiving focus."}]`),s={version:e,generatedAt:t,source:i,successCriteria:n,cards:o,items:a};export{o as cards,s as default,t as generatedAt,a as items,i as source,n as successCriteria,e as version};
